3	// repair runs from 0 (case broken) to 1 (case whole). The 3D core assembles as it rises.
4	export type CaseStatus = { status: string; tone: Tone; repair: number };
5	
6	export const CASE_EVENT = "case-status";
7	
8	const defaultRepair: Record<Tone, number> = { fault: 0, work: 0.5, ok: 1 };
9	
10	// The page tells one story: a case moving from failed to closed. Sections call this as they
11	// scroll into view; the backdrop, the accent colour, the HUD and the 3D core all follow it.
12	export function setCase(status: string, tone: Tone, repair: number = defaultRepair[tone]) {
13	  if (typeof document === "undefined") return;
14	  const root = document.documentElement;
15	  if (root.dataset.tone === tone && root.dataset.status === status) return;
16	  root.dataset.tone = tone;
17	  root.dataset.status = status;
18	  root.dataset.repair = String(repair);
19	  window.dispatchEvent(new CustomEvent<CaseStatus>(CASE_EVENT, { detail: { status, tone, repair } }));
20	}
21	
22	// While the pinned case scene is being scrolled, it writes the repair value here every frame
23	// so the 3D core follows the reader's scroll directly instead of jumping between steps.
24	export const caseLive: { repair: number | null } = { repair: null };
