19	float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
20	
21	float noise(vec2 p) {
22	  vec2 i = floor(p);
23	  vec2 f = fract(p);
24	  vec2 u = f * f * (3.0 - 2.0 * f);
25	  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
26	             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
27	}
28	
29	float fbm(vec2 p) {
30	  float v = 0.0;
31	  float a = 0.5;
32	  for (int i = 0; i < 5; i++) {
33	    v += a * noise(p);
34	    p = p * 2.02 + vec2(1.7, 9.2);
35	    a *= 0.5;
36	  }
37	  return v;
38	}
