40	void main() {
41	  vec2 uv = gl_FragCoord.xy / uRes;
42	  vec2 p = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;
43	  vec2 m = (uMouse - 0.5) * vec2(uRes.x / uRes.y, 1.0);
44	  float t = uTime * 0.05;
45	
46	  vec2 q = vec2(fbm(p * 1.3 + t + m * 0.25), fbm(p * 1.3 - t + 4.0 + uScroll));
47	  vec2 r = vec2(fbm(p * 1.7 + 3.0 * q + vec2(1.7, 9.2) + t * 1.4),
48	                fbm(p * 1.7 + 3.0 * q + vec2(8.3, 2.8) - t));
49	  float f = fbm(p * 1.5 + 3.2 * r);
50	
51	  float ribbons = smoothstep(0.38, 0.95, f + 0.25 * length(q));
52	  vec3 col = vec3(0.022, 0.03, 0.026);
53	  col = mix(col, uA * 0.5, ribbons * smoothstep(0.2, 0.9, r.x));
54	  col = mix(col, uB * 0.5, smoothstep(0.5, 1.0, r.y) * 0.75 * f);
55	
56	  float contour = abs(fract(f * 16.0) - 0.5);
57	  col += uA * 0.12 * smoothstep(0.05, 0.0, contour) * ribbons;
58	
59	  float d = length(p - m);
