84	  const shader = gl.createShader(type);
85	  if (!shader) return null;
86	  gl.shaderSource(shader, source);
87	  gl.compileShader(shader);
88	  return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null;
