91	// Fixed WebGL backdrop. Its colours follow the case tone, and it bends toward the pointer.
92	export function Backdrop() {
93	  const canvas = useRef<HTMLCanvasElement>(null);
94	
95	  useEffect(() => {
96	    const el = canvas.current;
97	    const gl = el?.getContext("webgl", { antialias: false, alpha: false, powerPreference: "low-power" });
98	    if (!el || !gl) return;
99	
100	    const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
101	    const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
102	    const program = gl.createProgram();
103	    if (!vertex || !fragment || !program) return;
104	    gl.attachShader(program, vertex);
105	    gl.attachShader(program, fragment);
106	    gl.linkProgram(program);
107	    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return;
108	    gl.useProgram(program);
109	
110	    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
111	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
112	    const position = gl.getAttribLocation(program, "p");
113	    gl.enableVertexAttribArray(position);
114	    gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
115	
116	    const uniform = (name: string) => gl.getUniformLocation(program, name);
117	    const uRes = uniform("uRes");
118	    const uTime = uniform("uTime");
119	    const uScroll = uniform("uScroll");
120	    const uMouse = uniform("uMouse");
121	    const uA = uniform("uA");
122	    const uB = uniform("uB");
123	
124	    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
125	    const initial = (document.documentElement.dataset.tone as Tone) ?? "fault";
126	    const a = [...palette[initial][0]];
127	    const b = [...palette[initial][1]];
128	    const mouse = { x: 0.5, y: 0.5 };
129	    let flow = 0;
130	    let boost = 0;
131	    let lastScroll = window.scrollY;
132	    let lastFrame = performance.now();
133	
134	    const draw = () => {
135	      gl.uniform2f(uRes, el.width, el.height);
136	      gl.uniform1f(uTime, reduced ? 20 : flow);
137	      gl.uniform1f(uScroll, window.scrollY * 0.0004);
138	      gl.uniform2f(uMouse, mouse.x, mouse.y);
139	      gl.uniform3f(uA, a[0], a[1], a[2]);
140	      gl.uniform3f(uB, b[0], b[1], b[2]);
141	      gl.drawArrays(gl.TRIANGLES, 0, 3);
142	    };
143	
144	    const resize = () => {
145	      // Render below native resolution: the image is soft by design and this keeps it cheap.
146	      const scale = Math.min(window.devicePixelRatio, 1.5) * 0.6;
147	      el.width = Math.floor(window.innerWidth * scale);
148	      el.height = Math.floor(window.innerHeight * scale);
149	      gl.viewport(0, 0, el.width, el.height);
150	      draw();
151	    };
152	
153	    const tick = () => {
154	      if (document.hidden) return;
155	      const now = performance.now();
156	      const delta = Math.min((now - lastFrame) / 1000, 0.1);
157	      lastFrame = now;
158	      const moved = Math.abs(window.scrollY - lastScroll);
159	      lastScroll = window.scrollY;
160	      boost += (Math.min(moved * 0.08, 7) - boost) * 0.08;
161	      flow += delta * (1 + boost);
162	      draw();
163	    };
164	
165	    const onTone = (event: Event) => {
166	      const [nextA, nextB] = palette[(event as CustomEvent<CaseStatus>).detail.tone];
167	      const onUpdate = reduced ? draw : undefined;
168	      gsap.to(a, { endArray: nextA, duration: 1.4, ease: "power2.out", overwrite: true, onUpdate });
169	      gsap.to(b, { endArray: nextB, duration: 1.4, ease: "power2.out", overwrite: true });
170	    };
171	
172	    const moveX = gsap.quickTo(mouse, "x", { duration: 1.4, ease: "power3" });
173	    const moveY = gsap.quickTo(mouse, "y", { duration: 1.4, ease: "power3" });
174	    const onPointer = (event: PointerEvent) => {
175	      moveX(event.clientX / window.innerWidth);
176	      moveY(1 - event.clientY / window.innerHeight);
177	    };
178	
179	    resize();
180	    window.addEventListener("resize", resize);
181	    window.addEventListener(CASE_EVENT, onTone);
182	    if (!reduced) {
183	      gsap.ticker.add(tick);
184	      window.addEventListener("pointermove", onPointer);
185	    }
186	
187	    return () => {
188	      gsap.ticker.remove(tick);
189	      window.removeEventListener("resize", resize);
190	      window.removeEventListener(CASE_EVENT, onTone);
191	      window.removeEventListener("pointermove", onPointer);
192	    };
193	  }, []);
