import type { Tone } from "@/lib/caseStatus";

export type AgentId = "coordinator" | "investigation" | "resolution" | "closure";
export type AgentState = "idle" | "active" | "waiting" | "done" | "error";
export type SpanKind = "agent" | "llm" | "tool" | "checkpoint" | "decision";
export type SpanStatus = "running" | "ok" | "error" | "fallback";
export type Attr = string | number | boolean;

// A neatlogs-style span. Times are milliseconds from the start of the run.
export type Span = {
  id: string;
  parentId: string | null;
  kind: SpanKind;
  name: string;
  agent: AgentId;
  startMs: number;
  endMs: number | null;
  status: SpanStatus;
  attrs: Record<string, Attr>;
  tokensIn?: number;
  tokensOut?: number;
  costUsd?: number;
};

// An Entire-style checkpoint. Each one is hash-linked to its parent so the chain is tamper evident.
export type Checkpoint = {
  id: string;
  seq: number;
  parentId: string | null;
  hash: string;
  agent: AgentId;
  label: string;
  atMs: number;
  state: Record<string, unknown>;
};

export type Cost = {
  llmUsd: number;
  infraUsd: number;
  totalUsd: number;
  tokensIn: number;
  tokensOut: number;
  llmCalls: number;
  toolCalls: number;
};

export type CaseRecord = {
  txn: string;
  merchant: string;
  fault: string;
  rootCause: string;
  fix: string;
  verification: string;
  humanInput: string;
};

export type LogLevel = "info" | "warn" | "error" | "ok";

export type LlmInfo = { provider: "ollama"; model: string; available: boolean; enabled: boolean };

export type Outcome = "resolved" | "escalated" | "failed" | "not_found" | "needs_info";

export type RunReport = {
  headline: string;
  rootCause: string;
  actions: string[];
  merchantMessage: string;
  kbEntry: string;
  narrated: boolean;
};

export type RunResult = {
  outcome: Outcome;
  summary: string;
  durationMs: number;
  memoryHit: boolean;
  pattern: string | null;
  spanCount: number;
  checkpointCount: number;
  chainValid: boolean;
  cost: Cost;
  report: RunReport | null;
};

export type RunMeta = {
  id: string;
  traceId: string;
  instruction: string;
  chaos: boolean;
  startedAt: string;
  llm: LlmInfo;
};

export type RunEvent =
  | { type: "run.start"; run: RunMeta }
  | { type: "agent"; agent: AgentId; state: AgentState }
  | { type: "span.start"; span: Span }
  | { type: "span.end"; span: Span }
  | { type: "log"; atMs: number; agent: AgentId; level: LogLevel; text: string }
  | { type: "checkpoint"; checkpoint: Checkpoint }
  | { type: "status"; status: string; tone: Tone; repair: number }
  | { type: "case"; patch: Partial<CaseRecord> }
  | { type: "cost"; cost: Cost }
  | { type: "run.end"; result: RunResult };

export type RunSummary = {
  id: string;
  instruction: string;
  startedAt: string;
  txn: string | null;
  pattern: string | null;
  outcome: Outcome;
  chaos: boolean;
  memoryHit: boolean;
  durationMs: number;
  toolCalls: number;
  llmCalls: number;
  costUsd: number;
};

export type StoredRun = { meta: RunMeta; events: RunEvent[]; summary: RunSummary | null };

export type RunOptions = {
  instruction: string;
  chaos?: boolean;
  llm?: boolean;
  // Multiplies every simulated delay. 1 is real time, 0 is instant (used by tests).
  speed?: number;
};

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

// Small JSON persistence. Prefers ./.data, falls back to the OS temp dir (read-only hosts such as Vercel).
const g = globalThis as unknown as { __resolverDir?: string };

function dataDir(): string {
  if (g.__resolverDir) return g.__resolverDir;
  const candidates = [process.env.RESOLVER_DATA_DIR, path.join(process.cwd(), ".data"), path.join(os.tmpdir(), "merchant-ops-resolver")];
  for (const dir of candidates) {
    if (!dir) continue;
    try {
      fs.mkdirSync(dir, { recursive: true });
      fs.accessSync(dir, fs.constants.W_OK);
      g.__resolverDir = dir;
      return dir;
    } catch {
      // try the next candidate
    }
  }
  g.__resolverDir = os.tmpdir();
  return g.__resolverDir;
}

export function readJson<T>(name: string, fallback: T): T {
  try {
    return JSON.parse(fs.readFileSync(path.join(dataDir(), name), "utf8")) as T;
  } catch {
    return fallback;
  }
}

export function writeJson(name: string, data: unknown) {
  try {
    const file = path.join(dataDir(), name);
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(data));
    fs.renameSync(tmp, file);
  } catch {
    // Persistence is best effort. The in-memory copy stays authoritative.
  }
}

// A simulated merchant-ops world: merchants, settlements, bank directory, KYC and risk data.
// The tools below are the only way agents read or change it. Every run gets a fresh copy.

export type FailureCode = "IFSC_ACCOUNT_MISMATCH" | "KYC_DOCUMENT_EXPIRED" | "RISK_VELOCITY_SPIKE";

export type Settlement = {
  txn: string;
  merchantId: string;
  amount: number;
  currency: "INR";
  status: "FAILED" | "HELD" | "PROCESSING" | "SETTLED";
  failureCode: FailureCode;
  failureMessage: string;
  beneficiary: { account: string; ifsc: string; name: string };
  rail: "NEFT" | "IMPS";
  settledAmount: number | null;
  retained: number;
  settleAt: number | null; // epoch ms when a PROCESSING settlement completes
  idempotencyKeys: string[];
};

export type Merchant = {
  id: string;
  name: string;
  city: string;
  segment: string;
  contactEmail: string;
  contactPhone: string;
  bank: { account: string; ifsc: string };
};

