import type { LlmInfo } from "@/lib/engine/types";

// Local Ollama client. llama2 has no tool calling, so it only writes reasoning text.
// Every decision that changes state is made by deterministic code, never by the model.
const HOST = process.env.OLLAMA_HOST ?? "http://127.0.0.1:11434";
export const MODEL = process.env.OLLAMA_MODEL ?? "llama2";

const g = globalThis as unknown as { __ollama?: { at: number; available: boolean } };

export async function ollamaStatus(): Promise<Omit<LlmInfo, "enabled">> {
  const cached = g.__ollama;
  if (cached && Date.now() - cached.at < 10_000) return { provider: "ollama", model: MODEL, available: cached.available };
  let available = false;
  try {
    const res = await fetch(`${HOST}/api/tags`, { signal: AbortSignal.timeout(1500), cache: "no-store" });
    if (res.ok) {
      const body = (await res.json()) as { models?: { name: string }[] };
      available = (body.models ?? []).some((m) => m.name === MODEL || m.name.startsWith(`${MODEL}:`));
    }
  } catch {
    available = false;
  }
  g.__ollama = { at: Date.now(), available };
  return { provider: "ollama", model: MODEL, available };
}

// Loads the model into memory ahead of the first run so the first call is not a cold start.
export async function warmModel() {
  try {
    await fetch(`${HOST}/api/generate`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ model: MODEL, prompt: "ok", stream: false, keep_alive: "30m", options: { num_predict: 1 } }),
      signal: AbortSignal.timeout(60_000),
    });
  } catch {
    // warming is best effort
  }
}

export type Thought = { text: string; tokensIn: number; tokensOut: number; ms: number };

export async function think(opts: { system: string; prompt: string; maxTokens?: number; timeoutMs?: number }): Promise<Thought | null> {
  const started = Date.now();
  try {
    const res = await fetch(`${HOST}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        model: MODEL,
        stream: false,
        keep_alive: "30m",
        messages: [
          { role: "system", content: opts.system },
          { role: "user", content: opts.prompt },
        ],
        options: { temperature: 0.2, num_predict: opts.maxTokens ?? 120, num_ctx: 2048 },
      }),
      signal: AbortSignal.timeout(opts.timeoutMs ?? 25_000),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { message?: { content?: string }; prompt_eval_count?: number; eval_count?: number };
    const text = clean(body.message?.content ?? "");
    if (!text) return null;
    return { text, tokensIn: body.prompt_eval_count ?? 0, tokensOut: body.eval_count ?? 0, ms: Date.now() - started };
  } catch {
    return null;
  }
}

// Strips the chatty wrappers llama2 likes to add, and keeps the text to plain sentences.
function clean(raw: string): string {
  let text = raw.trim();
  text = text.replace(/^(sure|certainly|of course|okay)[^\n]*\n+/i, "");
  text = text.replace(/^["']|["']$/g, "");
  text = text.replace(/[–—]/g, "-");
  return text.replace(/\n{3,}/g, "\n\n").trim();
}

import { createHash } from "node:crypto";
import { readJson, writeJson } from "@/lib/engine/persist";
import type { AgentId, Checkpoint } from "@/lib/engine/types";

// --- Per-run checkpoint chain (the Entire idea: save the context behind each decision) -------------

function link(parentHash: string, agent: string, label: string, state: unknown) {
  return createHash("sha256").update(`${parentHash}|${agent}|${label}|${JSON.stringify(state)}`).digest("hex");
}

export class CheckpointChain {
  readonly items: Checkpoint[] = [];

  create(agent: AgentId, label: string, state: Record<string, unknown>, atMs: number): Checkpoint {
    const parent = this.items.at(-1) ?? null;
    const hash = link(parent?.hash ?? "genesis", agent, label, state);
    const checkpoint: Checkpoint = {
      id: `ckpt_${this.items.length + 1}_${hash.slice(0, 7)}`,
      seq: this.items.length + 1,
      parentId: parent?.id ?? null,
      hash,
      agent,
      label,
      atMs,
      // Copy so later mutation of the live state can never rewrite history.
      state: JSON.parse(JSON.stringify(state)),
    };
    this.items.push(checkpoint);
    return checkpoint;
  }

  latest(): Checkpoint | null {
    return this.items.at(-1) ?? null;
  }

  // Recomputes every hash from genesis. False means a checkpoint was altered or removed.
  verify(): boolean {
    let parentHash = "genesis";
    for (const item of this.items) {
      if (link(parentHash, item.agent, item.label, item.state) !== item.hash) return false;
      parentHash = item.hash;
    }
    return true;
  }
}

// --- Cross-case memory: what past resolved cases teach the Investigation worker -------------------

export type MemoryEntry = {
  pattern: string;
  summary: string;
  // The smallest set of tools that produced the evidence for the diagnosis last time.
  minimalTools: string[];
  fix: string;
  resolvedCases: number;
  lastCheckpoint: string;
  lastResolvedAt: string;
  avgToolCalls: number;
  avgDurationMs: number;
};

const FILE = "memory.json";
const g = globalThis as unknown as { __memory?: Record<string, MemoryEntry> };

// One resolved case is already on record, so the first demo run shows a checkpoint hit.
function seed(): Record<string, MemoryEntry> {
  return {
    IFSC_ACCOUNT_MISMATCH: {
      pattern: "IFSC_ACCOUNT_MISMATCH",
      summary: "Settlement fails because the IFSC on file belongs to a different bank than the account.",
      minimalTools: ["verify_beneficiary"],
      fix: "Verify the beneficiary by penny drop, correct the IFSC, retrigger the settlement.",
      resolvedCases: 3,
      lastCheckpoint: "ckpt_5_9e41c0a",
      lastResolvedAt: "2026-10-02T09:14:00.000Z",
      avgToolCalls: 7,
      avgDurationMs: 6200,
    },
  };
}

function load(): Record<string, MemoryEntry> {
  if (!g.__memory) g.__memory = readJson<Record<string, MemoryEntry> | null>(FILE, null) ?? seed();
  return g.__memory;
}

export const memory = {
  all: () => Object.values(load()),
  find: (pattern: string): MemoryEntry | null => load()[pattern] ?? null,
  learn(entry: { pattern: string; summary: string; minimalTools: string[]; fix: string; checkpoint: string; toolCalls: number; durationMs: number }) {
    const store = load();
    const prev = store[entry.pattern];
    const n = (prev?.resolvedCases ?? 0) + 1;
    store[entry.pattern] = {
      pattern: entry.pattern,
      summary: entry.summary,
      minimalTools: entry.minimalTools,
      fix: entry.fix,
      resolvedCases: n,
      lastCheckpoint: entry.checkpoint,
      lastResolvedAt: new Date().toISOString(),
      avgToolCalls: prev ? Math.round((prev.avgToolCalls * (n - 1) + entry.toolCalls) / n) : entry.toolCalls,
      avgDurationMs: prev ? Math.round((prev.avgDurationMs * (n - 1) + entry.durationMs) / n) : entry.durationMs,
    };
    writeJson(FILE, store);
  },
  reset() {
    g.__memory = seed();
    writeJson(FILE, g.__memory);
  },
  clear() {
    g.__memory = {};
    writeJson(FILE, g.__memory);
  },
};

import type { Cost, RunSummary } from "@/lib/engine/types";

// Every number here is an assumption, not a measurement. Edit them to match the real business.
// Measured values (tool calls, tokens, duration) come from actual runs; prices turn them into dollars.
export const ASSUMPTIONS = {
  // Local llama2 costs nothing per token, so tokens are priced at a typical hosted 7B rate.
  llmUsdPerMTokIn: 0.2,
  llmUsdPerMTokOut: 0.2,
  infraUsdPerToolCall: 0.0004,
  computeUsdPerSecond: 0.00002,
  // What one routine case costs today with a human working across dashboards.
  humanMinutesPerCase: 38,
  humanUsdPerHour: 8,
  // Pricing of the product.
  priceUsdPerResolvedCase: 0.9,
  platformUsdPerMerchantMonth: 15,
  fixedUsdPerMonth: 400,
  startingCashUsd: 120000,
} as const;

export const HUMAN_USD_PER_CASE = (ASSUMPTIONS.humanMinutesPerCase / 60) * ASSUMPTIONS.humanUsdPerHour;

export function emptyCost(): Cost {
  return { llmUsd: 0, infraUsd: 0, totalUsd: 0, tokensIn: 0, tokensOut: 0, llmCalls: 0, toolCalls: 0 };
}

export function llmCost(tokensIn: number, tokensOut: number): number {
  return (tokensIn * ASSUMPTIONS.llmUsdPerMTokIn + tokensOut * ASSUMPTIONS.llmUsdPerMTokOut) / 1_000_000;
}

export type EconomicsSnapshot = {
  assumptions: typeof ASSUMPTIONS;
  humanUsdPerCase: number;
  measured: {
    runs: number;
    resolved: number;
    escalated: number;
    failed: number;
    autoResolveRate: number;
    avgCostUsd: number;
    avgDurationMs: number;
    avgToolCalls: number;
    totalCostUsd: number;
    humanCostAvoidedUsd: number;
    coldAvgToolCalls: number | null;
    warmAvgToolCalls: number | null;
    coldAvgDurationMs: number | null;
    warmAvgDurationMs: number | null;
  };
  recent: RunSummary[];
};

const avg = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);

export function snapshot(runs: RunSummary[]): EconomicsSnapshot {
  // Only cases the system really handled count. Unknown transactions say nothing about cost.
  const real = runs.filter((r) => r.outcome !== "not_found" && r.outcome !== "needs_info");
  const resolved = real.filter((r) => r.outcome === "resolved");
  const cold = real.filter((r) => !r.memoryHit);
  const warm = real.filter((r) => r.memoryHit);
  const totalCostUsd = real.reduce((sum, r) => sum + r.costUsd, 0);
  return {
    assumptions: ASSUMPTIONS,
    humanUsdPerCase: HUMAN_USD_PER_CASE,
    measured: {
      runs: real.length,
      resolved: resolved.length,
      escalated: real.filter((r) => r.outcome === "escalated").length,
      failed: real.filter((r) => r.outcome === "failed").length,
      autoResolveRate: real.length ? resolved.length / real.length : 0,
      avgCostUsd: real.length ? totalCostUsd / real.length : 0,
      avgDurationMs: avg(real.map((r) => r.durationMs)) ?? 0,
      avgToolCalls: avg(real.map((r) => r.toolCalls)) ?? 0,
      totalCostUsd,
      humanCostAvoidedUsd: resolved.length * HUMAN_USD_PER_CASE - totalCostUsd,
      coldAvgToolCalls: avg(cold.map((r) => r.toolCalls)),
      warmAvgToolCalls: avg(warm.map((r) => r.toolCalls)),
      coldAvgDurationMs: avg(cold.map((r) => r.durationMs)),
      warmAvgDurationMs: avg(warm.map((r) => r.durationMs)),
    },
    recent: runs.slice(0, 8),
  };
}

import { randomBytes } from "node:crypto";
import { CheckpointChain } from "@/lib/engine/checkpoints";
import { emptyCost, ASSUMPTIONS, llmCost } from "@/lib/engine/economics";
import { think } from "@/lib/engine/ollama";
import { seedWorld, type World } from "@/lib/engine/world";
import type { AgentId, AgentState, Attr, Checkpoint, Cost, LogLevel, RunEvent, Span, SpanKind, SpanStatus } from "@/lib/engine/types";

export class ToolTimeout extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ToolTimeout";
  }
}

type ToolOptions = { latency: number; attrs?: Record<string, Attr> };

const hex = (bytes: number) => randomBytes(bytes).toString("hex");

function brief(value: unknown, max = 150): string {
  const text = typeof value === "string" ? value : JSON.stringify(value);
  return text.length > max ? `${text.slice(0, max - 3)}...` : text;
}

// Everything one run needs: the world, the trace, the checkpoint chain, cost and the event stream.
export class RunContext {
  readonly id = `run_${hex(4)}`;
  readonly traceId = hex(16);
  readonly t0 = Date.now();
  readonly world: World = seedWorld();
  readonly chain = new CheckpointChain();
  readonly spans = new Map<string, Span>();
  readonly cost: Cost = emptyCost();
  readonly pending: Promise<unknown>[] = [];
  private chaosLeft: boolean;

  constructor(
    readonly speed: number,
    readonly chaos: boolean,
    readonly llmOn: boolean,
    readonly emit: (event: RunEvent) => void,
  ) {
    this.chaosLeft = chaos;
  }

  now() {
    return Date.now() - this.t0;
  }

  // Simulated latency. Scaled by speed so tests can run instantly.
  sleep(ms: number) {
    const scaled = ms * this.speed;
    return scaled <= 0 ? Promise.resolve() : new Promise<void>((resolve) => setTimeout(resolve, scaled));
  }

  // True exactly once when chaos is on: the first write to an external system times out.
  chaosHit() {
    if (!this.chaosLeft) return false;
    this.chaosLeft = false;
    return true;
  }

  log(agent: AgentId, level: LogLevel, text: string) {
    this.emit({ type: "log", atMs: this.now(), agent, level, text });
  }

  agent(agent: AgentId, state: AgentState) {
    this.emit({ type: "agent", agent, state });
  }

  status(status: string, tone: "fault" | "work" | "ok", repair: number) {
    this.emit({ type: "status", status, tone, repair });
  }

  pushCost() {
    const c = this.cost;
    c.totalUsd = c.llmUsd + c.infraUsd;
    this.emit({ type: "cost", cost: { ...c } });
  }

  startSpan(kind: SpanKind, name: string, agent: AgentId, parent: Span | null, attrs: Record<string, Attr> = {}): Span {
    const span: Span = {
      id: hex(8),
      parentId: parent?.id ?? null,
      kind,
      name,
      agent,
      startMs: this.now(),
      endMs: null,
      status: "running",
      attrs,
    };
    this.spans.set(span.id, span);
    this.emit({ type: "span.start", span: { ...span } });
    return span;
  }

  endSpan(span: Span, status: SpanStatus = "ok", extra: Partial<Pick<Span, "tokensIn" | "tokensOut" | "costUsd">> & { attrs?: Record<string, Attr> } = {}) {
    span.endMs = this.now();
    span.status = status;
    if (extra.attrs) span.attrs = { ...span.attrs, ...extra.attrs };
    if (extra.tokensIn !== undefined) span.tokensIn = extra.tokensIn;
    if (extra.tokensOut !== undefined) span.tokensOut = extra.tokensOut;
    if (extra.costUsd !== undefined) span.costUsd = extra.costUsd;
    this.emit({ type: "span.end", span: { ...span } });
  }

  // Runs an agent as a span, keeping the agent graph and the trace in step.
  async asAgent<T>(agent: AgentId, name: string, parent: Span | null, body: (span: Span) => Promise<T>): Promise<T> {
    const span = this.startSpan("agent", name, agent, parent);
    this.agent(agent, "active");
    try {
      const result = await body(span);
      this.endSpan(span, "ok");
      this.agent(agent, "done");
      return result;
    } catch (error) {
      this.endSpan(span, "error", { attrs: { error: error instanceof Error ? error.message : "unknown" } });
      this.agent(agent, "error");
      throw error;
    }
  }

  // One tool call: a span, a log line, simulated latency, and infrastructure cost.
  async tool<T>(agent: AgentId, parent: Span | null, name: string, args: Record<string, Attr>, options: ToolOptions, impl: () => T): Promise<T> {
    const span = this.startSpan("tool", name, agent, parent, { ...args, ...options.attrs });
    this.log(agent, "info", `${name}(${Object.values(args).map(String).join(", ")})`);
    await this.sleep(options.latency);
    this.cost.toolCalls += 1;
    this.cost.infraUsd += ASSUMPTIONS.infraUsdPerToolCall;
    try {
      const result = impl();
      this.endSpan(span, "ok", { attrs: { result: brief(result) }, costUsd: ASSUMPTIONS.infraUsdPerToolCall });
      this.pushCost();
      return result;
    } catch (error) {
      const message = error instanceof Error ? error.message : "tool failed";
      this.endSpan(span, "error", { attrs: { error: message }, costUsd: ASSUMPTIONS.infraUsdPerToolCall });
      this.pushCost();
      throw error;
    }
  }

  checkpoint(agent: AgentId, label: string, state: Record<string, unknown>, parent: Span | null): Checkpoint {
    const checkpoint = this.chain.create(agent, label, state, this.now());
    const span = this.startSpan("checkpoint", `checkpoint ${label}`, agent, parent, { id: checkpoint.id, hash: checkpoint.hash.slice(0, 12) });
    this.endSpan(span, "ok");
    this.emit({ type: "checkpoint", checkpoint });
    this.log(agent, "info", `Entire: saved ${checkpoint.id} (${label})`);
    return checkpoint;
  }

  // Asks llama2 for a short piece of reasoning text. Falls back to `fallback` when the model is off,
  // missing or slow, so the run never depends on it. Returns whether the model really wrote the text.
  async narrate(opts: {
    agent: AgentId;
    parent: Span | null;
    name: string;
    system: string;
    prompt: string;
    fallback: string;
    maxTokens?: number;
  }): Promise<{ text: string; narrated: boolean }> {
    if (!this.llmOn) return { text: opts.fallback, narrated: false };
    const span = this.startSpan("llm", opts.name, opts.agent, opts.parent, { provider: "ollama", mode: "narration" });
    const thought = await think({ system: opts.system, prompt: opts.prompt, maxTokens: opts.maxTokens });
    if (!thought) {
      this.endSpan(span, "fallback", { attrs: { reason: "model unavailable or too slow" } });
      this.log(opts.agent, "warn", "llama2 did not answer in time, used the built-in summary");
      return { text: opts.fallback, narrated: false };
    }
    const usd = llmCost(thought.tokensIn, thought.tokensOut);
    this.cost.llmCalls += 1;
    this.cost.tokensIn += thought.tokensIn;
    this.cost.tokensOut += thought.tokensOut;
    this.cost.llmUsd += usd;
    this.endSpan(span, "ok", { tokensIn: thought.tokensIn, tokensOut: thought.tokensOut, costUsd: usd, attrs: { latencyMs: thought.ms } });
    this.pushCost();
    return { text: thought.text, narrated: true };
  }

  // Starts a narration without blocking the agents. The run waits for it before it ends.
  narrateInBackground(opts: Parameters<RunContext["narrate"]>[0], onDone: (text: string, narrated: boolean) => void) {
    const task = this.narrate(opts).then((r) => onDone(r.text, r.narrated));
    this.pending.push(task);
    return task;
  }
}

export { brief };

import { memory } from "@/lib/engine/checkpoints";
import { RunContext, ToolTimeout } from "@/lib/engine/runtime";
import type { AgentId, Span } from "@/lib/engine/types";
import { IFSC_DIRECTORY, type Settlement } from "@/lib/engine/world";

// What the bank actually has on record. Used by the penny-drop check.
const BANK_LEDGER: Record<string, { ifsc: string; holder: string }> = {
  "50100234567890": { ifsc: "SBIN0000456", holder: "SHARMA KIRANA STORE" },
  "917020034411882": { ifsc: "UTIB0000789", holder: "RAO PHARMACY" },
  "003401556677889": { ifsc: "ICIC0002211", holder: "IYER SWEETS AND SNACKS" },
};

// Policy the Resolution worker must obey. The agents cannot argue their way past it.
export const AUTO_RELEASE_LIMIT_INR = 250000;
const FORBIDDEN_ACTIONS = new Set(["modify_kyc_status", "waive_kyc_requirement"]);

const jitter = (base: number) => Math.round(base + Math.random() * base * 0.6);

type Ctx = { ctx: RunContext; agent: AgentId; parent: Span | null };

function refresh(s: Settlement) {
  if (s.status === "PROCESSING" && s.settleAt !== null && Date.now() >= s.settleAt) {
    s.status = "SETTLED";
    s.settleAt = null;
  }
}

function settlementOf({ ctx }: Ctx, txn: string): Settlement {
  const s = ctx.world.settlements[txn];
  if (!s) throw new Error(`settlement ${txn} not found`);
  refresh(s);
  return s;
}

// ---- reads -------------------------------------------------------------------------------------

export function getSettlement(c: Ctx, txn: string) {
  return c.ctx.tool(c.agent, c.parent, "get_settlement", { txn }, { latency: jitter(150) }, () => ({ ...settlementOf(c, txn) }));
}

export function getMerchantProfile(c: Ctx, merchantId: string) {
  return c.ctx.tool(c.agent, c.parent, "get_merchant_profile", { merchantId }, { latency: jitter(170) }, () => {
    const m = c.ctx.world.merchants[merchantId];
    if (!m) throw new Error(`merchant ${merchantId} not found`);
    return { ...m };
  });
}

export function getKyc(c: Ctx, merchantId: string) {
  return c.ctx.tool(c.agent, c.parent, "get_kyc", { merchantId }, { latency: jitter(180) }, () => c.ctx.world.kyc[merchantId] ?? []);
}

export function getRiskSignals(c: Ctx, merchantId: string) {
  return c.ctx.tool(c.agent, c.parent, "get_risk_signals", { merchantId }, { latency: jitter(220) }, () => ({ ...c.ctx.world.risk[merchantId] }));
}

export function lookupIfsc(c: Ctx, ifsc: string) {
  return c.ctx.tool(c.agent, c.parent, "lookup_ifsc", { ifsc }, { latency: jitter(130) }, () => {
    const hit = IFSC_DIRECTORY[ifsc];
    return hit ? { found: true, ...hit } : { found: false };
  });
}

export function verifyBeneficiary(c: Ctx, account: string, ifscOnFile: string) {
  return c.ctx.tool(c.agent, c.parent, "verify_beneficiary", { account, ifscOnFile }, { latency: jitter(420), attrs: { method: "penny_drop" } }, () => {
    const real = BANK_LEDGER[account];
    if (!real) return { accountFound: false };
    return {
      accountFound: true,
      holder: real.holder,
      actualIfsc: real.ifsc,
      actualBank: IFSC_DIRECTORY[real.ifsc]?.bank ?? "unknown",
      ifscOnFileMatches: real.ifsc === ifscOnFile,
    };
  });
}

export function searchMemory(c: Ctx, pattern: string) {
  return c.ctx.tool(c.agent, c.parent, "search_memory", { pattern, store: "entire" }, { latency: jitter(90) }, () => {
    const hit = memory.find(pattern);
    return hit ? { hit: true, ...hit } : { hit: false };
  });
}

export function policyCheck(c: Ctx, action: string, amount?: number) {
  return c.ctx.tool(c.agent, c.parent, "policy_check", { action, ...(amount !== undefined ? { amount } : {}) }, { latency: jitter(60) }, () => {
    if (FORBIDDEN_ACTIONS.has(action)) return { allowed: false, reason: "Compliance status can only be changed by a human reviewer." };
    if (action === "release_hold" && amount !== undefined && amount > AUTO_RELEASE_LIMIT_INR) {
      return { allowed: false, reason: `Releases above INR ${AUTO_RELEASE_LIMIT_INR} need human approval.` };
    }
    return { allowed: true, reason: "Within autonomous limits." };
  });
}

// ---- writes ------------------------------------------------------------------------------------

export function updateBankIfsc(c: Ctx, merchantId: string, ifsc: string, txn: string) {
  return c.ctx.tool(c.agent, c.parent, "update_bank_ifsc", { merchantId, ifsc }, { latency: jitter(210) }, () => {
    const merchant = c.ctx.world.merchants[merchantId];
    merchant.bank.ifsc = ifsc;
    c.ctx.world.settlements[txn].beneficiary.ifsc = ifsc;
    return { updated: true, merchantId, ifsc };
  });
}

export async function retriggerSettlement(c: Ctx, txn: string, rail: "NEFT" | "IMPS", key: string) {
  const timeout = rail === "NEFT" && c.ctx.chaosHit();
  return c.ctx.tool(c.agent, c.parent, "retrigger_settlement", { txn, rail, idempotencyKey: key }, { latency: timeout ? 1200 : jitter(260) }, () => {
    if (timeout) throw new ToolTimeout("bank API timeout (504) after 1.2 s");
    const s = settlementOf(c, txn);
    if (s.idempotencyKeys.includes(key)) return { accepted: true, duplicate: true };
    s.idempotencyKeys.push(key);
    s.status = "PROCESSING";
    s.rail = rail;
    s.settledAmount = s.amount;
    s.settleAt = Date.now() + 650 * c.ctx.speed;
    return { accepted: true, duplicate: false, rail };
  });
}

export async function releaseHold(c: Ctx, txn: string, releaseAmount: number, retainAmount: number, key: string) {
  const timeout = c.ctx.chaosHit();
  return c.ctx.tool(c.agent, c.parent, "release_hold", { txn, release: releaseAmount, retain: retainAmount, idempotencyKey: key }, { latency: timeout ? 1200 : jitter(280) }, () => {
    if (timeout) throw new ToolTimeout("settlement API timeout (504) after 1.2 s");
    const s = settlementOf(c, txn);
    if (s.idempotencyKeys.includes(key)) return { accepted: true, duplicate: true };
    s.idempotencyKeys.push(key);
    s.status = "PROCESSING";
    s.settledAmount = releaseAmount;
    s.retained = retainAmount;
    s.settleAt = Date.now() + 650 * c.ctx.speed;
    return { accepted: true, duplicate: false, release: releaseAmount, retain: retainAmount };
  });
}

export async function requestRekyc(c: Ctx, merchantId: string, channel: "email" | "sms") {
  const timeout = channel === "email" && c.ctx.chaosHit();
  return c.ctx.tool(c.agent, c.parent, "request_rekyc", { merchantId, channel }, { latency: timeout ? 1200 : jitter(240) }, () => {
    if (timeout) throw new ToolTimeout("notification service timeout (504) after 1.2 s");
    c.ctx.world.rekyc.push({ merchantId, channel });
    return { requested: true, channel };
  });
}

export function writeKb(c: Ctx, txn: string, entry: string) {
  return c.ctx.tool(c.agent, c.parent, "write_kb", { txn }, { latency: jitter(220) }, () => {
    c.ctx.world.kb.push({ txn, entry });
    return { written: true, articleId: `KB-${txn}` };
  });
}

export function notifyMerchant(c: Ctx, merchantId: string, channel: string, body: string) {
  return c.ctx.tool(c.agent, c.parent, "notify_merchant", { merchantId, channel }, { latency: jitter(200) }, () => {
    c.ctx.world.notifications.push({ merchantId, channel, body });
    return { sent: true, channel };
  });
}

export function pollSettlement(c: Ctx, txn: string) {
  return c.ctx.tool(c.agent, c.parent, "get_settlement", { txn, purpose: "verify" }, { latency: jitter(180) }, () => ({ ...settlementOf(c, txn) }));
}

import { memory } from "@/lib/engine/checkpoints";
import { RunContext, ToolTimeout } from "@/lib/engine/runtime";
import * as tools from "@/lib/engine/tools";
import { AUTO_RELEASE_LIMIT_INR } from "@/lib/engine/tools";
import type { AgentId, Outcome, RunReport, Span } from "@/lib/engine/types";
import type { FailureCode, KycDoc, Merchant, RiskSignals, Settlement } from "@/lib/engine/world";

const SYSTEM = "You are part of an operations team inside a payments company. Answer in plain sentences. No lists, no markdown, no greetings.";

const inr = (n: number) => `INR ${n.toLocaleString("en-IN")}`;
const mask = (account: string) => `${"*".repeat(Math.max(account.length - 4, 0))}${account.slice(-4)}`;

// ---- diagnosis ---------------------------------------------------------------------------------

type Evidence = { tool: string; fact: string; weight: number };
export type Finding = { id: string; hypothesis: string; confidence: number; evidence: Evidence[] };
type Facts = {
  profile?: Merchant;
  kyc?: KycDoc[];
  risk?: RiskSignals;
  verify?: Awaited<ReturnType<typeof tools.verifyBeneficiary>>;
};
export type Diagnosis = {
  pattern: FailureCode;
  findings: Finding[];
  conflict: boolean;
  evidenceTools: string[];
  memoryHit: boolean;
  rootCause: string;
  facts: Facts;
};

// What a cold start sweeps: payments, KYC and risk data, in the order a human would open the dashboards.
const FULL_SWEEP: Record<FailureCode, string[]> = {
  IFSC_ACCOUNT_MISMATCH: ["get_merchant_profile", "get_kyc", "get_risk_signals", "lookup_ifsc", "verify_beneficiary"],
  KYC_DOCUMENT_EXPIRED: ["get_merchant_profile", "get_risk_signals", "get_kyc"],
  RISK_VELOCITY_SPIKE: ["get_merchant_profile", "get_kyc", "get_risk_signals"],
};

function analyze(s: Settlement, facts: Facts): { findings: Finding[]; rootCause: string } {
  if (s.failureCode === "IFSC_ACCOUNT_MISMATCH") {
    const v = facts.verify;
    if (v?.accountFound && v.actualIfsc && !v.ifscOnFileMatches) {
      return {
        rootCause: "Bank IFSC code mismatch",
        findings: [
          {
            id: "ifsc_mismatch",
            hypothesis: `The IFSC on file (${s.beneficiary.ifsc}) is wrong. Account ${mask(s.beneficiary.account)} is held at ${v.actualBank} (${v.actualIfsc}).`,
            confidence: 0.97,
            evidence: [{ tool: "verify_beneficiary", fact: `penny drop: account sits at ${v.actualIfsc}, holder ${v.holder}`, weight: 0.97 }],
          },
        ],
      };
    }
  }

  if (s.failureCode === "KYC_DOCUMENT_EXPIRED") {
    const doc = facts.kyc?.find((d) => d.status === "EXPIRED");
    if (doc) {
      return {
        rootCause: "KYC document expired",
        findings: [
          {
            id: "kyc_expired",
            hypothesis: `${doc.type} ${doc.id} expired on ${doc.expires}, so compliance froze the settlement.`,
            confidence: 0.99,
            evidence: [{ tool: "get_kyc", fact: `${doc.type} status EXPIRED since ${doc.expires}`, weight: 0.99 }],
          },
        ],
      };
    }
  }

  if (s.failureCode === "RISK_VELOCITY_SPIKE" && facts.risk) {
    const r = facts.risk;
    const benign: Evidence[] = [];
    if (r.sameWeekLastYear >= 3) benign.push({ tool: "get_risk_signals", fact: `same week last year ran ${r.sameWeekLastYear}x baseline`, weight: 0.2 });
    if (r.repeatCustomerShare >= 0.9) benign.push({ tool: "get_risk_signals", fact: `${Math.round(r.repeatCustomerShare * 100)}% repeat customers`, weight: 0.15 });
    if (Math.abs(r.avgTicketVsBaseline - 1) <= 0.1) benign.push({ tool: "get_risk_signals", fact: "average ticket size is normal", weight: 0.1 });
    if (r.chargebackRate < 0.003) benign.push({ tool: "get_risk_signals", fact: `chargeback rate ${(r.chargebackRate * 100).toFixed(1)}%`, weight: 0.1 });
    const benignScore = Math.min(0.3 + benign.reduce((sum, e) => sum + e.weight, 0), 0.95);

    const findings: Finding[] = [
      {
        id: "seasonal_spike",
        hypothesis: `The ${r.volumeVsBaseline}x volume is a festive-season order spike, not fraud.`,
        confidence: benignScore,
        evidence: benign,
      },
    ];
    const d = r.deviceCluster;
    if (d.sharedFingerprint && d.txns >= 10) {
      findings.push({
        id: "device_cluster",
        hypothesis: `${d.txns} payments in ${d.minutes} minutes share one device fingerprint (${inr(d.amount)}), which looks like card testing.`,
        confidence: 0.6 + (d.minutes <= 10 ? 0.1 : 0),
        evidence: [{ tool: "get_risk_signals", fact: `${d.txns} txns, ${d.minutes} min, one device fingerprint, ${inr(d.amount)}`, weight: 0.7 }],
      });
    }
    return { rootCause: findings.length > 1 ? "Seasonal spike, plus one suspicious device cluster" : "Seasonal volume spike", findings };
  }

  return { rootCause: "Unknown", findings: [] };
}

export async function investigate(ctx: RunContext, parent: Span, s: Settlement): Promise<Diagnosis> {
  return ctx.asAgent("investigation", "investigation.run", parent, async (span) => {
    const c = { ctx, agent: "investigation" as const, parent: span };
    const facts: Facts = {};

    // The first thing a good teammate does is ask what the team already learned from similar cases.
    const mem = await tools.searchMemory(c, s.failureCode);
    const memoryHit = mem.hit === true;
    let plan: string[];
    if (memoryHit && "minimalTools" in mem) {
      plan = mem.minimalTools;
      ctx.log("investigation", "ok", `Entire hit: ${mem.resolvedCases} similar cases resolved. Skipping the full sweep, running ${plan.length} targeted check${plan.length === 1 ? "" : "s"}.`);
    } else {
      plan = FULL_SWEEP[s.failureCode];
      ctx.log("investigation", "info", `No similar case on record. Sweeping payments, KYC and risk data (${plan.length} checks).`);
    }

    for (const name of plan) {
      if (name === "get_merchant_profile") facts.profile = await tools.getMerchantProfile(c, s.merchantId);
      else if (name === "get_kyc") facts.kyc = await tools.getKyc(c, s.merchantId);
      else if (name === "get_risk_signals") facts.risk = await tools.getRiskSignals(c, s.merchantId);
      else if (name === "lookup_ifsc") await tools.lookupIfsc(c, s.beneficiary.ifsc);
      else if (name === "verify_beneficiary") facts.verify = await tools.verifyBeneficiary(c, s.beneficiary.account, s.beneficiary.ifsc);
    }

    const { findings, rootCause } = analyze(s, facts);
    const best = [...findings].sort((a, b) => b.confidence - a.confidence);
    const conflict = best.length > 1 && best[1].confidence > 0.5;

    for (const f of findings) ctx.log("investigation", "info", `Finding (${Math.round(f.confidence * 100)}%): ${f.hypothesis}`);
    if (conflict) ctx.log("investigation", "warn", "Two findings point in opposite directions. Handing the conflict to the Coordinator.");

    // A cold start also asks the model to read the evidence aloud. A playbook hit does not need it.
    if (!memoryHit && best.length > 0) {
      void ctx.narrateInBackground(
        {
          agent: "investigation",
          parent: span,
          name: "llm.explain_evidence",
          system: SYSTEM,
          prompt: `Settlement failure: ${s.failureMessage}. Evidence: ${best.flatMap((f) => f.evidence.map((e) => e.fact)).join("; ")}. In one sentence, what is the most likely cause?`,
          fallback: best[0].hypothesis,
          maxTokens: 70,
        },
        (text, narrated) => narrated && ctx.log("investigation", "info", `llama2 read of the evidence: ${text}`),
      );
    }

    const winners = conflict ? best : best.slice(0, 1);
    const evidenceTools = [...new Set(winners.flatMap((f) => f.evidence.map((e) => e.tool)))];
    ctx.checkpoint("investigation", "diagnosis", { txn: s.txn, pattern: s.failureCode, findings: best.map((f) => ({ id: f.id, confidence: f.confidence })), evidenceTools }, span);
    return { pattern: s.failureCode, findings: best, conflict, evidenceTools, memoryHit, rootCause, facts };
  });
}

// ---- decisions (Coordinator) -------------------------------------------------------------------

export type Decision =
  | { action: "correct_ifsc"; ifsc: string; rationale: string; arbitrated: false }
  | { action: "escalate_kyc"; rationale: string; arbitrated: false }
  | { action: "partial_release"; release: number; retain: number; rationale: string; arbitrated: true }
  | { action: "escalate_unknown"; rationale: string; arbitrated: false };

export async function decide(ctx: RunContext, parent: Span, s: Settlement, diag: Diagnosis): Promise<Decision> {
  const top = diag.findings[0];

  if (diag.conflict) {
    // The Coordinator settles disagreements with a stated rule, so the outcome is auditable.
    const span = ctx.startSpan("decision", "coordinator.arbitrate", "coordinator", parent, { findings: diag.findings.map((f) => f.id).join(" vs ") });
    ctx.agent("coordinator", "active");
    const cluster = diag.facts.risk?.deviceCluster;
    const exposure = cluster?.amount ?? 0;
    const share = exposure / s.amount;
    const release = s.amount - exposure;
    const safe = share < 0.1 && release <= AUTO_RELEASE_LIMIT_INR;
    const rationale = safe
      ? `Both findings hold. The suspicious cluster is ${(share * 100).toFixed(1)}% of the settlement, so release ${inr(release)} and retain ${inr(exposure)} for human review.`
      : "The suspicious cluster is too large to release around, so the whole settlement stays held for human review.";
    ctx.log("coordinator", "warn", `Disagreement: ${diag.findings.map((f) => `${f.id} ${Math.round(f.confidence * 100)}%`).join(" vs ")}.`);
    ctx.log("coordinator", "ok", `Ruling: ${rationale}`);
    void ctx.narrateInBackground(
      {
        agent: "coordinator",
        parent: span,
        name: "llm.explain_ruling",
        system: SYSTEM,
        prompt: `Two analysts disagree. One says: ${diag.findings[0].hypothesis} The other says: ${diag.findings[1].hypothesis} The coordinator ruled: ${rationale} Explain the ruling to a risk officer in two sentences.`,
        fallback: rationale,
        maxTokens: 90,
      },
      (text, narrated) => narrated && ctx.log("coordinator", "info", `llama2 on the ruling: ${text}`),
    );
    ctx.checkpoint("coordinator", "arbitration", { txn: s.txn, ruling: safe ? "partial_release" : "hold", exposure, release }, span);
    ctx.endSpan(span, "ok", { attrs: { ruling: safe ? "partial_release" : "hold", exposureInr: exposure } });
    ctx.status("Disagreement settled", "work", 0.5);
    if (safe) return { action: "partial_release", release, retain: exposure, rationale, arbitrated: true };
    return { action: "escalate_unknown", rationale, arbitrated: false };
  }

  if (s.failureCode === "IFSC_ACCOUNT_MISMATCH" && diag.facts.verify?.actualIfsc) {
    return { action: "correct_ifsc", ifsc: diag.facts.verify.actualIfsc, rationale: top.hypothesis, arbitrated: false };
  }
  if (s.failureCode === "KYC_DOCUMENT_EXPIRED" && top) {
    return { action: "escalate_kyc", rationale: top.hypothesis, arbitrated: false };
  }
  return { action: "escalate_unknown", rationale: "The evidence does not support a safe automatic fix.", arbitrated: false };
}

// ---- Resolution --------------------------------------------------------------------------------

type Strategy = { rail: "NEFT" | "IMPS"; channel: "email" | "sms"; idemKey: string; completed: string[]; attempt: number };
type Step = { id: string; run: (state: Strategy) => Promise<unknown> };

export type Resolved = {
  outcome: Outcome;
  verified: boolean;
  fix: string;
  verification: string;
  retries: number;
  skippedOnResume: number;
};

export async function resolve(ctx: RunContext, parent: Span, s: Settlement, decision: Decision): Promise<Resolved> {
  return ctx.asAgent("resolution", "resolution.run", parent, async (span) => {
    const c = { ctx, agent: "resolution" as const, parent: span };
    const state: Strategy = { rail: "NEFT", channel: "email", idemKey: `idem_${ctx.id}_${s.txn}`, completed: [], attempt: 0 };
    let retries = 0;
    let skippedOnResume = 0;

    const steps: Step[] = [];
    if (decision.action === "correct_ifsc") {
      steps.push(
        { id: "policy", run: () => tools.policyCheck(c, "update_bank_details") },
        { id: "update_ifsc", run: () => tools.updateBankIfsc(c, s.merchantId, decision.ifsc, s.txn) },
        { id: "retrigger", run: (st) => tools.retriggerSettlement(c, s.txn, st.rail, st.idemKey) },
      );
    } else if (decision.action === "partial_release") {
      steps.push(
        { id: "policy", run: () => tools.policyCheck(c, "release_hold", decision.release) },
        { id: "release", run: (st) => tools.releaseHold(c, s.txn, decision.release, decision.retain, st.idemKey) },
      );
    } else {
      steps.push(
        {
          id: "policy",
          run: async () => {
            const verdict = await tools.policyCheck(c, "modify_kyc_status");
            if (!verdict.allowed) ctx.log("resolution", "warn", `Policy blocks the direct fix: ${verdict.reason} Taking the safe path instead.`);
          },
        },
        { id: "request_rekyc", run: (st) => tools.requestRekyc(c, s.merchantId, st.channel) },
      );
    }

    // Checkpoint before touching anything, so even the very first step can be resumed.
    ctx.checkpoint("resolution", "pre-fix", { txn: s.txn, action: decision.action, ...state }, span);

    for (;;) {
      try {
        for (const step of steps) {
          if (state.completed.includes(step.id)) continue;
          await step.run(state);
          state.completed.push(step.id);
          ctx.checkpoint("resolution", step.id, { txn: s.txn, action: decision.action, ...state }, span);
          if (step.id === "update_ifsc" || step.id === "release") {
            ctx.status("Fix applied", "work", 0.7);
            ctx.emit({ type: "case", patch: { fix: fixText(decision) } });
          }
        }
        break;
      } catch (error) {
        if (!(error instanceof ToolTimeout) || state.attempt >= 2) throw error;
        retries += 1;
        state.attempt += 1;
        ctx.log("resolution", "error", error.message);
        ctx.agent("resolution", "waiting");

        // Entire: resume from the last saved checkpoint instead of starting the case over.
        const last = ctx.chain.latest();
        if (last) {
          const saved = last.state as unknown as Strategy;
          state.completed = [...saved.completed];
          skippedOnResume = state.completed.filter((id) => id !== "policy").length;
          ctx.log("resolution", "ok", `Entire: resumed from ${last.id} (${last.label}). ${state.completed.length} finished step${state.completed.length === 1 ? "" : "s"} will not repeat.`);
        }

        // Try a different approach rather than hammering the one that just failed.
        const retry = ctx.startSpan("decision", "resolution.retry_strategy", "resolution", span, { attempt: state.attempt });
        let strategy = "retry with the same idempotency key";
        if (decision.action === "correct_ifsc") {
          state.rail = "IMPS";
          strategy = "switch rail NEFT to IMPS, same idempotency key so a double payout is impossible";
        } else if (decision.action === "escalate_kyc" || decision.action === "escalate_unknown") {
          state.channel = "sms";
          strategy = "switch channel email to SMS";
        }
        ctx.log("resolution", "info", `Strategy: ${strategy}.`);
        await ctx.sleep(350 * state.attempt);
        ctx.endSpan(retry, "ok", { attrs: { strategy } });
        ctx.agent("resolution", "active");
      }
    }

    // Verification. The case is never closed on the strength of a successful write alone.
    const verify = ctx.startSpan("decision", "resolution.verify", "resolution", span);
    const vc = { ctx, agent: "resolution" as const, parent: verify };
    let latest = await tools.pollSettlement(vc, s.txn);
    const expected = decision.action === "partial_release" ? decision.release : s.amount;
    const wantsSettled = decision.action === "correct_ifsc" || decision.action === "partial_release";
    for (let i = 0; wantsSettled && latest.status !== "SETTLED" && i < 6; i++) {
      ctx.log("resolution", "info", `Status is ${latest.status}, checking again.`);
      await ctx.sleep(300);
      latest = await tools.pollSettlement(vc, s.txn);
    }

    let outcome: Outcome;
    let verification: string;
    if (wantsSettled) {
      const ok = latest.status === "SETTLED" && latest.settledAmount === expected;
      outcome = ok ? "resolved" : "failed";
      verification = ok ? `status=SETTLED, ${inr(expected)} confirmed via API` : `status=${latest.status}, could not confirm the settlement`;
    } else {
      const held = latest.status === "HELD" && ctx.world.rekyc.length > 0;
      outcome = held ? "escalated" : "failed";
      verification = held ? "Settlement is safely held and a re-KYC request is on record" : "Could not confirm a safe state";
    }
    ctx.log("resolution", outcome === "failed" ? "error" : "ok", verification);
    ctx.endSpan(verify, outcome === "failed" ? "error" : "ok", { attrs: { outcome, verification } });
    if (outcome === "resolved") ctx.status("Verified", "ok", 0.92);
    ctx.emit({ type: "case", patch: { verification } });

    return { outcome, verified: outcome === "resolved", fix: fixText(decision), verification, retries, skippedOnResume };
  });
}

function fixText(d: Decision): string {
  if (d.action === "correct_ifsc") return `IFSC corrected to ${d.ifsc}, settlement retriggered`;
  if (d.action === "partial_release") return `${inr(d.release)} released, ${inr(d.retain)} retained for review`;
  if (d.action === "escalate_kyc") return "Re-KYC requested, human review needed";
  return "No safe automatic fix, escalated";
}

// ---- Closure -----------------------------------------------------------------------------------

export async function close(
  ctx: RunContext,
  parent: Span,
  s: Settlement,
  diag: Diagnosis,
  decision: Decision,
  res: Resolved,
): Promise<RunReport> {
  return ctx.asAgent("closure", "closure.run", parent, async (span) => {
    const c = { ctx, agent: "closure" as const, parent: span };
    const merchant = ctx.world.merchants[s.merchantId];
    const resolved = res.outcome === "resolved";

    const kbEntry = `${s.failureCode}: ${diag.rootCause}. Fix: ${res.fix}. Evidence tools: ${diag.evidenceTools.join(", ")}. Outcome: ${res.outcome}.`;
    const fallbackMessage = resolved
      ? `Hello ${merchant.name}, your settlement of ${inr(s.amount)} (txn ${s.txn}) is now complete. ${res.fix}. No action is needed from you.`
      : `Hello ${merchant.name}, your settlement (txn ${s.txn}) needs one more step from our team. We have started it and will update you shortly.`;

    // The message is drafted while the knowledge base is written, so neither waits for the other.
    const drafting = ctx.narrate({
      agent: "closure",
      parent: span,
      name: "llm.draft_merchant_message",
      system: SYSTEM,
      prompt: `Write a short, polite message of at most three sentences to the owner of ${merchant.name}. Situation: settlement ${s.txn} of ${inr(s.amount)} ${resolved ? "had a problem that is now fixed and verified" : "needs a human review"}. What was done: ${res.fix}. Do not invent details.`,
      fallback: fallbackMessage,
      maxTokens: 110,
    });
    const kb = await tools.writeKb(c, s.txn, kbEntry);
    ctx.log("closure", "ok", `Knowledge base article ${kb.articleId} written.`);
    const drafted = await drafting;
    await tools.notifyMerchant(c, s.merchantId, "email", drafted.text);
    ctx.log("closure", "ok", `Merchant notified by email.${drafted.narrated ? " Message drafted by llama2." : ""}`);

    const final = ctx.checkpoint("closure", "closed", { txn: s.txn, outcome: res.outcome, kb: kb.articleId }, span);
    if (res.outcome === "resolved" || res.outcome === "escalated") {
      memory.learn({
        pattern: s.failureCode,
        summary: `${diag.rootCause}.`,
        minimalTools: diag.evidenceTools,
        fix: res.fix,
        checkpoint: final.id,
        toolCalls: ctx.cost.toolCalls,
        durationMs: ctx.now(),
      });
      ctx.log("closure", "info", "Entire: pattern saved, so the next similar case starts with this playbook.");
    }

    ctx.status(resolved ? "Closed, verified" : "Escalated to human", resolved ? "ok" : "work", resolved ? 1 : 0.85);
    ctx.emit({ type: "case", patch: {} });

    const actions = [
      diag.memoryHit ? "Reused a playbook from Entire memory" : "Swept payments, KYC and risk data",
      decision.arbitrated ? "Coordinator ruled on a disagreement" : null,
      res.fix,
      res.retries > 0 ? `Recovered from ${res.retries} failed call${res.retries === 1 ? "" : "s"} by resuming a checkpoint` : null,
      res.verification,
    ].filter((a): a is string => a !== null);

    return {
      headline: resolved ? `Case ${s.txn} closed and verified` : `Case ${s.txn} escalated with everything prepared`,
      rootCause: diag.rootCause,
      actions,
      merchantMessage: drafted.text,
      kbEntry,
      narrated: drafted.narrated,
    };
  });
}

