import { readJson, writeJson } from "@/lib/engine/persist";
import type { RunEvent, RunMeta, RunSummary, StoredRun } from "@/lib/engine/types";

// Runs live in memory and the newest ones are mirrored to disk, so a restart keeps the history.
const FILE = "runs.json";
const KEEP = 40;
const g = globalThis as unknown as { __runs?: Map<string, StoredRun> };

function runs(): Map<string, StoredRun> {
  if (!g.__runs) {
    const saved = readJson<StoredRun[]>(FILE, []);
    // Saved newest first. The Map keeps insertion order oldest first, so insert in reverse.
    g.__runs = new Map([...saved].reverse().map((run) => [run.meta.id, run]));
  }
  return g.__runs;
}

export const store = {
  start(meta: RunMeta): StoredRun {
    const run: StoredRun = { meta, events: [], summary: null };
    runs().set(meta.id, run);
    return run;
  },
  append(id: string, event: RunEvent) {
    runs().get(id)?.events.push(event);
  },
  finish(id: string, summary: RunSummary) {
    const all = runs();
    const run = all.get(id);
    if (run) run.summary = summary;
    while (all.size > KEEP) all.delete(all.keys().next().value as string);
    writeJson(FILE, [...all.values()].reverse());
  },
  get: (id: string) => runs().get(id) ?? null,
  summaries(): RunSummary[] {
    return [...runs().values()]
      .reverse()
      .map((r) => r.summary)
      .filter((s): s is RunSummary => s !== null);
  },
  clear() {
    runs().clear();
    writeJson(FILE, []);
  },
};

import { close, decide, investigate, resolve } from "@/lib/engine/agents";
import { ollamaStatus } from "@/lib/engine/ollama";
import { RunContext } from "@/lib/engine/runtime";
import { store } from "@/lib/engine/store";
import * as tools from "@/lib/engine/tools";
import type { Outcome, RunEvent, RunOptions, RunReport, RunResult, Span, StoredRun } from "@/lib/engine/types";

const SYSTEM = "You are part of an operations team inside a payments company. Answer in plain sentences. No lists, no markdown, no greetings.";

// Runs one case end to end and streams every event to `sink`. Never throws: a failure becomes a result.
export async function executeRun(options: RunOptions, sink: (event: RunEvent) => void): Promise<StoredRun> {
  const status = await ollamaStatus();
  const llmOn = (options.llm ?? true) && status.available;
  let ctx!: RunContext;
  const emit = (event: RunEvent) => {
    store.append(ctx.id, event);
    try {
      sink(event);
    } catch {
      // The client may have gone away. The run still finishes and is stored.
    }
  };
  ctx = new RunContext(options.speed ?? 1, options.chaos ?? false, llmOn, emit);
  const meta = {
    id: ctx.id,
    traceId: ctx.traceId,
    instruction: options.instruction,
    chaos: options.chaos ?? false,
    startedAt: new Date(ctx.t0).toISOString(),
    llm: { ...status, enabled: llmOn },
  };
  const stored = store.start(meta);
  emit({ type: "run.start", run: meta });
  ctx.pushCost();

  let result: RunResult;
  let txn: string | null = null;
  let pattern: string | null = null;
  try {
    const out = await coordinate(ctx, options.instruction);
    result = out.result;
    txn = out.txn;
    pattern = out.pattern;
  } catch (error) {
    ctx.log("coordinator", "error", `Run failed: ${error instanceof Error ? error.message : "unknown error"}`);
    ctx.agent("coordinator", "error");
    result = finish(ctx, "failed", "The run stopped on an unexpected error.", false, null, null);
  }

  emit({ type: "run.end", result });
  store.finish(ctx.id, {
    id: ctx.id,
    instruction: options.instruction,
    startedAt: meta.startedAt,
    txn,
    pattern,
    outcome: result.outcome,
    chaos: meta.chaos,
    memoryHit: result.memoryHit,
    durationMs: result.durationMs,
    toolCalls: result.cost.toolCalls,
    llmCalls: result.cost.llmCalls,
    costUsd: result.cost.totalUsd,
  });
  return stored;
}

function finish(ctx: RunContext, outcome: Outcome, summary: string, memoryHit: boolean, pattern: string | null, report: RunReport | null): RunResult {
  const durationMs = ctx.now();
  // Compute time is the one cost that depends on how long the run took.
  const computeUsd = (durationMs / 1000) * 0.00002;
  ctx.cost.infraUsd += computeUsd;
  ctx.pushCost();
  return {
    outcome,
    summary,
    durationMs,
    memoryHit,
    pattern,
    spanCount: ctx.spans.size,
    checkpointCount: ctx.chain.items.length,
    chainValid: ctx.chain.verify(),
    cost: { ...ctx.cost, totalUsd: ctx.cost.llmUsd + ctx.cost.infraUsd },
    report,
  };
}

async function coordinate(ctx: RunContext, instruction: string): Promise<{ result: RunResult; txn: string | null; pattern: string | null }> {
  return ctx.asAgent("coordinator", "coordinator.run", null, async (root: Span) => {
    const c = { ctx, agent: "coordinator" as const, parent: root };
    ctx.status("Case received", "fault", 0);
    ctx.emit({ type: "case", patch: { humanInput: "One instruction" } });
    ctx.log("coordinator", "info", `Instruction received: "${instruction}"`);

    const txn = instruction.match(/\b(\d{4,6})\b/)?.[1] ?? null;
    if (!txn) {
      ctx.log("coordinator", "warn", "No transaction id in the instruction. Asking the operator for one.");
      ctx.status("Needs a transaction id", "fault", 0);
      return { result: finish(ctx, "needs_info", "Include a transaction id such as #48213 so the case can be found.", false, null, null), txn, pattern: null };
    }

    let s;
    try {
      s = await tools.getSettlement(c, txn);
    } catch {
      ctx.log("coordinator", "warn", `No settlement found for txn ${txn}. Nothing was changed.`);
      ctx.status("Case not found", "fault", 0);
      return { result: finish(ctx, "not_found", `No settlement exists for txn ${txn}. Nothing was changed.`, false, null, null), txn, pattern: null };
    }

    const merchant = ctx.world.merchants[s.merchantId];
    ctx.emit({ type: "case", patch: { txn, merchant: merchant.name, fault: s.status === "FAILED" ? "Settlement failed" : "Settlement held" } });
    ctx.status(s.status === "FAILED" ? "Settlement failed" : "Settlement held", "fault", 0);
    ctx.log("coordinator", "info", `Case: ${s.failureMessage}`);

    // The plan is deterministic. llama2 only explains it, in the background.
    ctx.log("coordinator", "info", "Plan: Investigation finds the cause, Resolution applies only what policy allows and verifies it against the real system, Closure documents and informs the merchant.");
    void ctx.narrateInBackground(
      {
        agent: "coordinator",
        parent: root,
        name: "llm.explain_plan",
        system: SYSTEM,
        prompt: `Case: ${s.failureMessage}. In two sentences, describe the plan for three workers named Investigation, Resolution and Closure.`,
        fallback: "Investigate, fix within policy, verify, then document.",
        maxTokens: 80,
      },
      (text, narrated) => narrated && ctx.log("coordinator", "info", `llama2 on the plan: ${text}`),
    );
    ctx.checkpoint("coordinator", "plan", { txn, pattern: s.failureCode, workers: ["investigation", "resolution", "closure"] }, root);
    ctx.status("Planning", "work", 0.2);

    ctx.agent("coordinator", "waiting");
    const diag = await investigate(ctx, root, s);
    ctx.agent("coordinator", "active");
    ctx.status("Root cause found", "work", 0.4);
    ctx.emit({ type: "case", patch: { rootCause: diag.rootCause } });

    const decision = await decide(ctx, root, s, diag);
    ctx.log("coordinator", "info", `Decision: ${decision.action}. ${decision.rationale}`);

    ctx.agent("coordinator", "waiting");
    const res = await resolve(ctx, root, s, decision);
    const report = await close(ctx, root, s, diag, decision, res);
    ctx.agent("coordinator", "active");

    // Explanations that are still being written must land in the trace before the run ends.
    await Promise.allSettled(ctx.pending);

    const seconds = (ctx.now() / 1000).toFixed(1);
    const summary =
      res.outcome === "resolved"
        ? `Settlement ${txn} verified as settled in ${seconds} s.`
        : res.outcome === "escalated"
          ? `Handled safely in ${seconds} s. A human decision is still needed.`
          : `Could not complete the fix. ${res.verification}.`;
    return { result: finish(ctx, res.outcome, summary, diag.memoryHit, s.failureCode, report), txn, pattern: s.failureCode };
  });
}

import { MODEL } from "@/lib/engine/ollama";
import type { Attr, Span, StoredRun } from "@/lib/engine/types";

// Exports a run as OpenTelemetry (OTLP/JSON) spans, so any OTel-compatible trace viewer can open it.
type OtlpValue = { stringValue: string } | { intValue: string } | { doubleValue: number } | { boolValue: boolean };

function value(v: Attr): OtlpValue {
  if (typeof v === "boolean") return { boolValue: v };
  if (typeof v === "number") return Number.isInteger(v) ? { intValue: String(v) } : { doubleValue: v };
  return { stringValue: v };
}

function attributes(span: Span) {
  const attrs: Record<string, Attr> = { "agent.id": span.agent, "span.kind.resolver": span.kind, ...span.attrs };
  if (span.kind === "llm") {
    attrs["gen_ai.system"] = "ollama";
    attrs["gen_ai.request.model"] = MODEL;
  }
  if (span.tokensIn !== undefined) attrs["gen_ai.usage.input_tokens"] = span.tokensIn;
  if (span.tokensOut !== undefined) attrs["gen_ai.usage.output_tokens"] = span.tokensOut;
  if (span.costUsd !== undefined) attrs["cost.usd"] = span.costUsd;
  return Object.entries(attrs).map(([key, v]) => ({ key, value: value(v) }));
}

export function toOtlp(run: StoredRun) {
  const startNs = BigInt(new Date(run.meta.startedAt).getTime()) * 1_000_000n;
  const ns = (ms: number) => String(startNs + BigInt(Math.round(ms)) * 1_000_000n);

  // The last event for a span id is its final state.
  const final = new Map<string, Span>();
  for (const event of run.events) if (event.type === "span.start" || event.type === "span.end") final.set(event.span.id, event.span);

  return {
    resourceSpans: [
      {
        resource: {
          attributes: [
            { key: "service.name", value: { stringValue: "merchant-ops-resolver" } },
            { key: "run.id", value: { stringValue: run.meta.id } },
            { key: "run.instruction", value: { stringValue: run.meta.instruction } },
          ],
        },
        scopeSpans: [
          {
            scope: { name: "merchant-ops-resolver.engine", version: "0.1.0" },
            spans: [...final.values()].map((span) => ({
              traceId: run.meta.traceId,
              spanId: span.id,
              ...(span.parentId ? { parentSpanId: span.parentId } : {}),
              name: span.name,
              kind: 1,
              startTimeUnixNano: ns(span.startMs),
              endTimeUnixNano: ns(span.endMs ?? span.startMs),
              attributes: attributes(span),
              status: { code: span.status === "error" ? 2 : 1 },
            })),
          },
        ],
      },
    ],
  };
}

import { executeRun } from "@/lib/engine/run";
import { store } from "@/lib/engine/store";
