for (;;) {
  const { done, value } = await reader.read();
  if (done) break;
  buf += dec.decode(value, { stream: true });
  let i;
  while ((i = buf.indexOf("\n\n")) >= 0) {
    const line = buf.slice(0, i).replace(/^data: /, "");
    buf = buf.slice(i + 2);
    events.push(JSON.parse(line));
  }
}
const counts = {};
for (const e of events) counts[e.type] = (counts[e.type] ?? 0) + 1;
console.log("events:", JSON.stringify(counts));
for (const e of events) {
  if (e.type === "log") console.log(`  [${String(e.atMs).padStart(5)}ms] ${e.agent.padEnd(13)} ${e.level.padEnd(5)} ${e.text.slice(0, verbose === "1" ? 400 : 150)}`);
  if (e.type === "status") console.log(`  STATUS ${e.tone} ${e.status} ${e.repair}`);
}
const end = events.find((e) => e.type === "run.end");
const start = events.find((e) => e.type === "run.start");
console.log("run:", start.run.id, "llm:", JSON.stringify(start.run.llm));
console.log("RESULT:", JSON.stringify({ ...end.result, report: end.result.report ? { ...end.result.report, merchantMessage: end.result.report.merchantMessage.slice(0, 160) } : null }, null, 1));

