// The model drafts the merchant message while Resolution is still working, assuming the plan succeeds.
// If the real outcome differs, Closure discards the draft and uses the accurate built-in wording.
export type Draft = { expectedResolved: boolean; promise: Promise<{ text: string; narrated: boolean }> };

export function startDraft(ctx: RunContext, parent: Span, s: Settlement, decision: Decision, diag: Diagnosis): Draft {
  const expectedResolved = decision.action === "correct_ifsc" || decision.action === "partial_release";
  const merchant = ctx.world.merchants[s.merchantId];
  const plain = plainSummary(s, decision, diag, expectedResolved);
  const promise = ctx.narrate({
    agent: "closure",
    parent,
    name: "llm.draft_merchant_message",
    system: SYSTEM,
    prompt: `Write a short, polite message of at most three sentences to the ${merchant.name} team. Begin with "Hello ${merchant.name} team,". Say exactly this and nothing more: ${plain} Do not invent details, names, dates or promises.`,
    fallback: `Hello ${merchant.name} team, ${plain}`,
    maxTokens: 85,
  });
  ctx.pending.push(promise);
  return { expectedResolved, promise };
}

export async function close(
  ctx: RunContext,
  parent: Span,
  s: Settlement,
  diag: Diagnosis,
  decision: Decision,
  res: Resolved,
  draft: Draft,
): Promise<RunReport> {
  return ctx.asAgent("closure", "closure.run", parent, async (span) => {
    const c = { ctx, agent: "closure" as const, parent: span };
    const merchant = ctx.world.merchants[s.merchantId];
    const resolved = res.outcome === "resolved";

    const kbEntry = `${s.failureCode}: ${diag.rootCause}. Fix: ${res.fix}. Evidence tools: ${diag.evidenceTools.join(", ")}. Outcome: ${res.outcome}.`;
    const kb = await tools.writeKb(c, s.txn, kbEntry);
    ctx.log("closure", "ok", `Knowledge base article ${kb.articleId} written.`);

    const drafted = await draft.promise;
    const useDraft = drafted.narrated && draft.expectedResolved === resolved;
    if (drafted.narrated && !useDraft) ctx.log("closure", "warn", "The outcome differed from the drafted message, so the accurate built-in wording is used instead.");
    const message = useDraft ? drafted.text : `Hello ${merchant.name} team, ${plainSummary(s, decision, diag, resolved)}`;
    await tools.notifyMerchant(c, s.merchantId, "email", message);
    ctx.log("closure", "ok", `Merchant notified by email.${useDraft ? " Message drafted by llama2." : ""}`);

