  active: "working",
  waiting: "waiting",
  done: "done",
  error: "failed",
};

const stateColor: Record<AgentState, string> = {
  idle: "text-white/25",
  active: "text-[var(--tone)]",
  waiting: "text-teal/70",
  done: "text-lime",
  error: "text-ember",
};

// The live agent graph. Each node follows the state events the engine emits.
export function AgentGraph({ agents }: { agents: Record<AgentId, AgentState> }) {
  return (
    <svg viewBox="0 0 640 250" role="img" aria-label="Agent graph: the Coordinator directs the Investigation, Resolution and Closure workers" className="w-full">
      <defs>
        <filter id="node-glow" x="-30%" y="-50%" width="160%" height="200%">
          <feGaussianBlur stdDeviation="6" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {wires.map((wire) => {
        const active = agents[wire.to] === "active";
        const done = agents[wire.to] === "done";
        return (
          <g key={wire.to}>
            <path d={wire.d} fill="none" stroke="currentColor" strokeWidth="1.5" className={done ? "text-lime/50" : active ? "text-[var(--tone)]" : "text-white/15"} />
            {active && (
              <path
                d={wire.d}
                fill="none"
                stroke="var(--tone)"
                strokeWidth="4"
                strokeLinecap="round"
                pathLength={1}
                strokeDasharray="0.06 1"
                strokeDashoffset="0.06"
                className="animate-pulse-travel"
                style={{ filter: "drop-shadow(0 0 6px var(--tone))" }}
              />
            )}
          </g>
        );
      })}

      {nodes.map((node) => {
        const state = agents[node.id];
        const live = state === "active";
        return (
          <g key={node.id} transform={`translate(${node.x - W / 2} ${node.y})`} className={stateColor[state]} filter={live ? "url(#node-glow)" : undefined}>
            <rect
              width={W}
              height={H}
              rx="2"
              fill="rgb(11 14 12 / 0.85)"
              stroke="currentColor"
              strokeWidth={live ? 1.75 : 1}
              strokeDasharray={state === "waiting" ? "4 4" : undefined}
            />
            <text x="14" y="25" fill="#f2f5ee" fontSize="14" fontWeight="600" className="font-display">
              {node.title}
            </text>
            <text x="14" y="42" fill="#9ba39a" fontSize="10.5" className="font-sans">
              {node.role}
            </text>
            <text x={W - 12} y="17" textAnchor="end" fill="currentColor" fontSize="9" letterSpacing="1.4" className="font-mono uppercase">
              {stateText[state]}
            </text>
          </g>
        );
      })}
    </svg>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { AGENT_LABEL } from "@/components/console/format";
import type { LogLine } from "@/components/console/runState";
import type { LogLevel } from "@/lib/engine/types";

const levelStyle: Record<LogLevel, string> = {
  info: "text-ink/80",
  ok: "text-lime",
  warn: "text-ember/90",
  error: "text-ember font-semibold",
};

const levelMark: Record<LogLevel, string> = { info: " ", ok: "+", warn: "!", error: "x" };

export function LogPanel({ logs, running }: { logs: LogLine[]; running: boolean }) {
  const box = useRef<HTMLDivElement>(null);

  // Follow the log while the reader is at the bottom, but never fight a reader who scrolled up.
  useEffect(() => {
    const el = box.current;
    if (!el) return;
    if (el.scrollHeight - el.scrollTop - el.clientHeight < 120) el.scrollTop = el.scrollHeight;
  }, [logs.length]);

  return (
    <div ref={box} role="log" aria-live="off" className="max-h-[26rem] overflow-y-auto px-1 py-2 font-mono text-[12.5px] leading-relaxed">
      {logs.length === 0 && <p className="px-3 py-6 text-mute">The run log fills in as the agents work. Pick a case and press Run.</p>}
      {logs.map((line, i) => (
        <div key={i} className="grid grid-cols-[3.6rem_6.4rem_1fr] gap-x-3 rounded-[2px] px-3 py-[3px] hover:bg-white/[0.04]">
          <span className="text-mute tabular-nums">{(line.atMs / 1000).toFixed(2)}s</span>
          <span className="text-mute">{AGENT_LABEL[line.agent]}</span>
          <span className={levelStyle[line.level]}>
            <span aria-hidden="true" className="mr-2 inline-block w-2 text-center">
              {levelMark[line.level]}
            </span>
            {line.text}
          </span>
        </div>
      ))}
      {running && (
        <div className="px-3 py-1 text-mute">
          <span aria-hidden="true" className="animate-blink inline-block h-3.5 w-2 translate-y-0.5 bg-ink" />
        </div>
      )}
    </div>
  );
}

"use client";

import { Download } from "lucide-react";
import { useMemo, useState } from "react";
import { AGENT_LABEL, fmtMs, fmtUsd } from "@/components/console/format";
import type { Span, SpanKind } from "@/lib/engine/types";

const kindBar: Record<SpanKind, string> = {
  agent: "bg-white/25",
  llm: "bg-teal",
  tool: "bg-lime/80",
  checkpoint: "bg-ink",
  decision: "bg-ink/70",
};

const kindLabel: Record<SpanKind, string> = {
  agent: "agent",
  llm: "llm",
  tool: "tool",
  checkpoint: "checkpoint",
  decision: "decision",
};

// A neatlogs-style waterfall: every agent run, model call, tool call, retry and checkpoint on one timeline.
export function TracePanel({ spans, elapsedMs, runId, done }: { spans: Span[]; elapsedMs: number; runId: string | null; done: boolean }) {
  const [open, setOpen] = useState<string | null>(null);

  const rows = useMemo(() => {
    const byId = new Map(spans.map((s) => [s.id, s]));
    const depth = (s: Span): number => (s.parentId && byId.get(s.parentId) ? depth(byId.get(s.parentId)!) + 1 : 0);
    return spans.map((s) => ({ span: s, depth: depth(s) }));
  }, [spans]);

  const total = Math.max(elapsedMs, ...spans.map((s) => s.endMs ?? s.startMs), 1);
  const errors = spans.filter((s) => s.status === "error").length;
  const tokens = spans.reduce((sum, s) => sum + (s.tokensIn ?? 0) + (s.tokensOut ?? 0), 0);

  return (
    <div>
      <div className="label flex flex-wrap items-center gap-x-5 gap-y-2 border-b border-line px-4 py-3 text-mute">
        <span>{spans.length} spans</span>
        <span className={errors ? "text-ember" : ""}>{errors} errors</span>
        <span>{tokens} tokens</span>
        <span className="tabular-nums">{fmtMs(total)} total</span>
        <span className="ml-auto flex items-center gap-4">
          {(Object.keys(kindBar) as SpanKind[]).map((k) => (
            <span key={k} className="hidden items-center gap-1.5 md:flex">
              <span aria-hidden="true" className={`size-2 ${kindBar[k]}`} />
              {kindLabel[k]}
            </span>
          ))}
          {runId && done && (
            <a href={`/api/runs/${runId}/trace`} className="flex items-center gap-1.5 text-ink hover:text-lime" download>
              <Download aria-hidden="true" className="size-3.5" />
              OTLP JSON
            </a>
          )}
        </span>
      </div>

      <div className="max-h-[26rem] overflow-y-auto py-1">
        {rows.length === 0 && <p className="px-4 py-6 font-mono text-[12.5px] text-mute">No spans yet.</p>}
        {rows.map(({ span, depth }) => {
          const end = span.endMs ?? total;
          const left = (span.startMs / total) * 100;
          const width = Math.max(((end - span.startMs) / total) * 100, span.kind === "checkpoint" ? 0.6 : 0.5);
          const bar = span.status === "error" ? "bg-ember" : span.status === "fallback" ? "bg-ember/50" : kindBar[span.kind];
          const expanded = open === span.id;
          return (
            <div key={span.id}>
              <button
                type="button"
                onClick={() => setOpen(expanded ? null : span.id)}
                aria-expanded={expanded}
                className="grid w-full grid-cols-[minmax(0,14rem)_1fr_4.2rem] items-center gap-x-3 px-4 py-[3px] text-left font-mono text-[12px] hover:bg-white/[0.04] md:grid-cols-[minmax(0,17rem)_1fr_4.5rem]"
              >
                <span className="truncate" style={{ paddingLeft: depth * 12 }}>
                  <span className={span.status === "error" ? "text-ember" : "text-ink/90"}>{span.name}</span>
                </span>
                <span className="relative h-3 bg-white/[0.05]">
                  <span
                    className={`absolute inset-y-0 ${bar} ${span.endMs === null ? "animate-blink" : ""}`}
                    style={{ left: `${left}%`, width: `${Math.min(width, 100 - left)}%` }}
                  />
                </span>
                <span className="text-right text-mute tabular-nums">{span.endMs === null ? "..." : fmtMs(span.endMs - span.startMs)}</span>
              </button>
              {expanded && (
                <div className="mx-4 mb-2 rounded-[2px] border border-line bg-black/30 px-3 py-2 font-mono text-[11.5px] leading-relaxed text-mute">
                  <p>
                    {AGENT_LABEL[span.agent]} / {kindLabel[span.kind]} / status {span.status}
                    {span.costUsd !== undefined && ` / ${fmtUsd(span.costUsd)}`}
                    {span.tokensIn !== undefined && ` / ${span.tokensIn} in, ${span.tokensOut ?? 0} out`}
                  </p>
                  {Object.entries(span.attrs).map(([key, value]) => (
                    <p key={key} className="break-words">
                      <span className="text-ink/70">{key}</span> {String(value)}
                    </p>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { ShieldCheck, ShieldAlert } from "lucide-react";
import { AGENT_LABEL, fmtMs } from "@/components/console/format";
import type { LogLine } from "@/components/console/runState";
import type { Checkpoint } from "@/lib/engine/types";

// The Entire idea: the context behind every decision is saved, hash-linked, and a retry resumes from it.
export function CheckpointPanel({ checkpoints, logs, chainValid }: { checkpoints: Checkpoint[]; logs: LogLine[]; chainValid: boolean | null }) {
  const resumedFrom = new Set<string>();
  for (const line of logs) {
    const hit = line.text.match(/resumed from (ckpt_\w+)/);
    if (hit) resumedFrom.add(hit[1]);
  }

  return (
    <div>
      <div className="label flex items-center justify-between gap-4 border-b border-line px-4 py-3 text-mute">
        <span>{checkpoints.length} checkpoints, each hash-linked to its parent</span>
        {chainValid !== null && (
          <span className={`flex items-center gap-1.5 ${chainValid ? "text-lime" : "text-ember"}`}>
            {chainValid ? <ShieldCheck aria-hidden="true" className="size-3.5" /> : <ShieldAlert aria-hidden="true" className="size-3.5" />}
            {chainValid ? "chain verified" : "chain broken"}
          </span>
        )}
      </div>

      <ol className="max-h-[26rem] overflow-y-auto px-4 py-4">
        {checkpoints.length === 0 && <li className="font-mono text-[12.5px] text-mute">Checkpoints appear as each agent finishes a step.</li>}
        {checkpoints.map((c, i) => (
          <li key={c.id} className="relative grid grid-cols-[1.25rem_1fr] gap-x-3 pb-4 last:pb-0">
            <span aria-hidden="true" className="relative flex justify-center">
              <span className={`mt-1.5 size-2.5 ${resumedFrom.has(c.id) ? "bg-lime" : "bg-white/40"}`} />
              {i < checkpoints.length - 1 && <span className="absolute top-4 bottom-[-1rem] w-px bg-white/15" />}
            </span>
            <div>
              <p className="flex flex-wrap items-baseline gap-x-3 font-mono text-[12.5px]">
                <span className="text-ink">{c.id}</span>
                <span className="text-lime">{c.label}</span>
                <span className="text-mute">
                  {AGENT_LABEL[c.agent]} at {fmtMs(c.atMs)}
                </span>
                {resumedFrom.has(c.id) && <span className="label rounded-[2px] border border-lime/60 px-1.5 py-0.5 text-lime">resumed from here</span>}
              </p>
              <p className="font-mono text-[11px] break-all text-mute" title={c.hash}>
                sha256 {c.hash.slice(0, 32)}... {c.parentId ? `parent ${c.parentId}` : "genesis"}
              </p>
              <details className="mt-1">
                <summary className="label cursor-pointer text-mute hover:text-ink">saved state</summary>
                <pre className="mt-1 max-h-40 overflow-auto rounded-[2px] border border-line bg-black/30 p-2 font-mono text-[11px] leading-relaxed text-mute">
                  {JSON.stringify(c.state, null, 2)}
                </pre>
              </details>
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import type { MemoryEntry } from "@/lib/engine/checkpoints";

// What the team has learned from past cases. A repeat case skips the sweep and runs the saved playbook.
export function MemoryPanel({ refreshKey, patternInRun }: { refreshKey: number; patternInRun: string | null }) {
  const [entries, setEntries] = useState<MemoryEntry[] | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await fetch("/api/memory", { cache: "no-store" });
      setEntries(((await res.json()) as { entries: MemoryEntry[] }).entries);
    } catch {
      setEntries([]);
    }
  }, []);

  useEffect(() => {
    // Deferred so the state update happens in a callback, not synchronously inside the effect.
    const id = setTimeout(load, 0);
    return () => clearTimeout(id);
  }, [load, refreshKey]);

  async function reset(mode: "reset" | "clear") {
    setBusy(true);
    try {
      const res = await fetch(`/api/memory?mode=${mode}`, { method: "DELETE" });
      setEntries(((await res.json()) as { entries: MemoryEntry[] }).entries);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      <div className="label flex flex-wrap items-center justify-between gap-3 border-b border-line px-4 py-3 text-mute">
        <span>Entire memory, shared across cases</span>
        <span className="flex gap-2">
          <button type="button" disabled={busy} onClick={() => reset("clear")} className="rounded-[2px] border border-line px-2.5 py-1.5 text-ink transition-colors hover:border-ember hover:text-ember disabled:opacity-50">
            Forget everything
          </button>
          <button type="button" disabled={busy} onClick={() => reset("reset")} className="rounded-[2px] border border-line px-2.5 py-1.5 text-ink transition-colors hover:border-lime hover:text-lime disabled:opacity-50">
            Restore seed
          </button>
        </span>
      </div>
      <div className="max-h-[26rem] overflow-y-auto px-4 py-3">
        {entries === null && <p className="font-mono text-[12.5px] text-mute">Loading...</p>}
        {entries?.length === 0 && (
          <p className="font-mono text-[12.5px] text-mute">
            Nothing learned yet. Run a case: the next time the same kind of failure comes in, the Investigation worker will start from the saved playbook instead of sweeping every system.
          </p>
        )}
        {entries?.map((entry) => (
          <article key={entry.pattern} className={`mb-3 rounded-[2px] border px-3.5 py-3 last:mb-0 ${entry.pattern === patternInRun ? "border-lime/60" : "border-line"}`}>
            <p className="flex flex-wrap items-baseline justify-between gap-2 font-mono text-[12.5px]">
              <span className="text-ink">{entry.pattern}</span>
              <span className="text-lime">{entry.resolvedCases} cases learned</span>
            </p>
            <p className="mt-1 text-[13px] leading-snug text-mute">{entry.summary}</p>
            <dl className="mt-2 grid grid-cols-[6.5rem_1fr] gap-y-1 font-mono text-[12px]">
              <dt className="text-mute">playbook</dt>
              <dd>{entry.minimalTools.join(", ")}</dd>
              <dt className="text-mute">fix</dt>
              <dd>{entry.fix}</dd>
              <dt className="text-mute">avg run</dt>
              <dd>
                {entry.avgToolCalls} tool calls, {(entry.avgDurationMs / 1000).toFixed(1)} s
              </dd>
              <dt className="text-mute">last checkpoint</dt>
              <dd>{entry.lastCheckpoint}</dd>
            </dl>
          </article>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fmtMs, fmtUsd } from "@/components/console/format";
import type { EconomicsSnapshot } from "@/lib/engine/economics";
import type { Cost, RunResult } from "@/lib/engine/types";

// The cfo.ai idea: price the agent like a real product. Measured numbers come from real runs;
// the prices that turn them into dollars are assumptions, listed at the bottom.
export function MoneyPanel({ cost, result, refreshKey }: { cost: Cost; result: RunResult | null; refreshKey: number }) {
  const [eco, setEco] = useState<EconomicsSnapshot | null>(null);
  const [merchants, setMerchants] = useState(200);
  const [casesPer, setCasesPer] = useState(8);

  useEffect(() => {
    let cancelled = false;
    const id = setTimeout(async () => {
      try {
        const res = await fetch("/api/economics", { cache: "no-store" });
        const body = (await res.json()) as EconomicsSnapshot;
        if (!cancelled) setEco(body);
      } catch {
        // the panel simply keeps its last snapshot
      }
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(id);
    };
  }, [refreshKey]);

  const a = eco?.assumptions;
  const human = eco?.humanUsdPerCase ?? 5.07;
  const m = eco?.measured;

  // Monthly model, driven by the measured cost per case.
  const avgCost = m && m.runs > 0 ? m.avgCostUsd : cost.totalUsd || 0.004;
  const autoRate = m && m.runs > 0 ? m.autoResolveRate : 0.7;
  const cases = merchants * casesPer;
  const resolved = cases * autoRate;
  const escalated = cases - resolved;
  const revenue = a ? merchants * a.platformUsdPerMerchantMonth + resolved * a.priceUsdPerResolvedCase : 0;
  const spend = a ? a.fixedUsdPerMonth + cases * avgCost + escalated * human : 0;
  const net = revenue - spend;
  const margin = revenue > 0 ? net / revenue : 0;
  const runway = a && net < 0 ? a.startingCashUsd / -net : null;
  const saved = resolved * human;

  const ratio = cost.totalUsd > 0 ? human / cost.totalUsd : null;

  return (
    <div className="max-h-[32rem] overflow-y-auto">
      <div className="grid gap-px border-b border-line bg-line sm:grid-cols-3">
        <Stat label="This case, all in" value={fmtUsd(cost.totalUsd)} sub={`${cost.toolCalls} tool calls, ${cost.llmCalls} model calls, ${cost.tokensIn + cost.tokensOut} tokens`} />
        <Stat label="Same case by hand" value={fmtUsd(human)} sub={a ? `${a.humanMinutesPerCase} min at $${a.humanUsdPerHour}/h (assumed)` : ""} />
        <Stat label="Agent vs human" value={ratio ? `${Math.round(ratio).toLocaleString("en-US")}x cheaper` : "-"} sub={result ? `finished in ${fmtMs(result.durationMs)}` : "run a case to measure"} tone />
      </div>

      <div className="grid gap-6 px-4 py-5 md:grid-cols-2">
        <section>
          <h3 className="label mb-3 text-mute">Compounding, measured across your runs</h3>
          {m && m.runs > 0 ? (
            <div className="space-y-3 font-mono text-[12px]">
              <Compare label="tool calls" cold={m.coldAvgToolCalls} warm={m.warmAvgToolCalls} fmt={(v) => v.toFixed(1)} />
              <Compare label="duration" cold={m.coldAvgDurationMs} warm={m.warmAvgDurationMs} fmt={fmtMs} />
              <p className="text-mute">
                {m.runs} runs, {m.resolved} resolved, {m.escalated} escalated. Cold means no saved playbook, warm means an Entire memory hit. Run the same kind of case twice to see the gap.
              </p>
            </div>
          ) : (
            <p className="font-mono text-[12px] text-mute">No completed runs yet.</p>
          )}
        </section>

        <section>
          <h3 className="label mb-3 text-mute">Monthly model, one business built on this</h3>
          <div className="space-y-3">
            <Slider label="Merchants" value={merchants} min={20} max={2000} step={20} onChange={setMerchants} />
            <Slider label="Cases per merchant per month" value={casesPer} min={1} max={30} step={1} onChange={setCasesPer} />
          </div>
          <dl className="mt-4 grid grid-cols-[1fr_auto] gap-y-1.5 font-mono text-[12.5px]">
            <dt className="text-mute">Cases handled</dt>
            <dd className="text-right tabular-nums">{cases.toLocaleString("en-US")}</dd>
            <dt className="text-mute">Resolved without a human</dt>
            <dd className="text-right tabular-nums">{Math.round(autoRate * 100)}% (measured)</dd>
            <dt className="text-mute">Revenue</dt>
            <dd className="text-right tabular-nums">{fmtUsd(revenue)}</dd>
            <dt className="text-mute">Cost (agents, fixed, human escalations)</dt>
            <dd className="text-right tabular-nums">{fmtUsd(spend)}</dd>
            <dt className="text-mute">Gross margin</dt>
            <dd className={`text-right tabular-nums ${margin >= 0 ? "text-lime" : "text-ember"}`}>{(margin * 100).toFixed(1)}%</dd>
            <dt className="text-mute">Runway</dt>
            <dd className="text-right tabular-nums">{runway ? `${runway.toFixed(1)} months` : "profitable"}</dd>
            <dt className="text-mute">Ops cost saved for merchants</dt>
            <dd className="text-right tabular-nums">{fmtUsd(saved)}/mo</dd>
          </dl>
        </section>
      </div>

      {a && (
        <p className="border-t border-line px-4 py-3 font-mono text-[11px] leading-relaxed text-mute">
          Assumptions, not measurements: local llama2 is free, so tokens are priced at ${a.llmUsdPerMTokIn}/M in and ${a.llmUsdPerMTokOut}/M out (typical hosted 7B); ${a.infraUsdPerToolCall} per tool call; ${a.priceUsdPerResolvedCase} per resolved
          case plus ${a.platformUsdPerMerchantMonth} per merchant per month; ${a.fixedUsdPerMonth} fixed per month; ${a.startingCashUsd.toLocaleString("en-US")} starting cash. Edit them in lib/engine/economics.ts.
        </p>
      )}
    </div>
  );
}

function Stat({ label, value, sub, tone = false }: { label: string; value: string; sub: string; tone?: boolean }) {
  return (
    <div className="bg-[rgb(11_14_12)] px-4 py-4">
      <p className="label text-mute">{label}</p>
      <p className={`display mt-2 text-3xl ${tone ? "tone" : ""}`}>{value}</p>
      <p className="mt-1 font-mono text-[11px] text-mute">{sub}</p>
    </div>
  );
}

function Compare({ label, cold, warm, fmt }: { label: string; cold: number | null; warm: number | null; fmt: (v: number) => string }) {
  const max = Math.max(cold ?? 0, warm ?? 0, 1);
  const row = (name: string, value: number | null, className: string) => (
    <div className="grid grid-cols-[3.2rem_1fr_4.5rem] items-center gap-3">
      <span className="text-mute">{name}</span>
      <span className="h-2.5 bg-white/[0.06]">
        {value !== null && <span className={`block h-full ${className}`} style={{ width: `${(value / max) * 100}%` }} />}
      </span>
      <span className="text-right tabular-nums">{value === null ? "no runs" : fmt(value)}</span>
    </div>
  );
  return (
    <div>
      <p className="mb-1.5 text-ink/80">{label}</p>
      <div className="space-y-1.5">
        {row("cold", cold, "bg-ember/80")}
        {row("warm", warm, "bg-lime")}
      </div>
    </div>
  );
}

function Slider({ label, value, min, max, step, onChange }: { label: string; value: number; min: number; max: number; step: number; onChange: (v: number) => void }) {
  return (
    <label className="block">
      <span className="flex justify-between font-mono text-[12px]">
        <span className="text-mute">{label}</span>
        <span className="tabular-nums">{value.toLocaleString("en-US")}</span>
      </span>
      <input type="range" min={min} max={max} step={step} value={value} onChange={(e) => onChange(Number(e.target.value))} className="mt-1 w-full accent-[#c8f53c]" />
    </label>
  );
}

"use client";

import { ArrowRight, Loader2 } from "lucide-react";
import { PRESETS } from "@/lib/engine/world";

type Props = {
  instruction: string;
  onInstruction: (value: string) => void;
  chaos: boolean;
  onChaos: (value: boolean) => void;
  llm: boolean;
  onLlm: (value: boolean) => void;
  llmReady: boolean | null;
  model: string;
  running: boolean;
  onRun: () => void;
};

export function InstructionPanel({ instruction, onInstruction, chaos, onChaos, llm, onLlm, llmReady, model, running, onRun }: Props) {
  return (
    <form
      className="glass glass-tint"
      onSubmit={(event) => {
        event.preventDefault();
        if (!running) onRun();
      }}
    >
      <div className="label flex items-center justify-between border-b border-line px-5 py-3.5">
        <label htmlFor="instruction">One instruction</label>
        <span className="text-mute">{instruction.length}/400</span>
      </div>

      <div className="px-5 pt-4">
        <textarea
          id="instruction"
          value={instruction}
          onChange={(event) => onInstruction(event.target.value)}
          maxLength={400}
          rows={3}
          spellCheck={false}
          className="w-full resize-none rounded-[2px] border border-line bg-black/30 px-3.5 py-3 font-mono text-[13px] leading-relaxed text-ink outline-none placeholder:text-mute focus:border-lime"
          placeholder="Describe the case. Include a transaction id, for example #48213."
        />
        <ul className="mt-3 grid gap-2">
          {PRESETS.map((preset) => (
            <li key={preset.id}>
              <button
                type="button"
                onClick={() => onInstruction(preset.instruction)}
                aria-pressed={instruction === preset.instruction}
                className={`label flex w-full items-center justify-between gap-3 rounded-[2px] border px-3 py-2.5 text-left transition-colors ${
                  instruction === preset.instruction ? "border-lime/70 text-lime" : "border-line text-ink hover:border-lime/60"
                }`}
              >
                <span>{preset.label}</span>
                <span className="text-mute normal-case tracking-normal">{preset.detail}</span>
              </button>
            </li>
          ))}
        </ul>
      </div>

      <div className="space-y-3 px-5 pt-4">
        <Toggle checked={chaos} onChange={onChaos} title="Break something" detail="The first call to an external system times out. Watch it recover from a checkpoint." />
        <Toggle
          checked={llm && llmReady === true}
          onChange={onLlm}
          disabled={llmReady !== true}
          title={`Write with ${model}`}
          detail={
            llmReady === null
              ? "Checking for a local Ollama model..."
              : llmReady
                ? "The local model explains rulings and drafts the merchant message. It never makes a decision."
                : `Ollama or ${model} was not found, so built-in wording is used. Decisions are unaffected.`
          }
        />
      </div>

      <div className="px-5 py-5">
        <button
          type="submit"
          disabled={running || instruction.trim().length < 3}
          className="label flex w-full items-center justify-between gap-4 rounded-[2px] border border-lime bg-lime px-5 py-4 text-void transition-colors duration-200 hover:border-ink hover:bg-ink disabled:cursor-not-allowed disabled:opacity-60"
        >
          {running ? "Agents are working" : "Run the case"}
          {running ? <Loader2 aria-hidden="true" className="size-4 animate-spin" /> : <ArrowRight aria-hidden="true" className="size-4" />}
        </button>
      </div>
    </form>
  );
}

function Toggle({ checked, onChange, title, detail, disabled = false }: { checked: boolean; onChange: (v: boolean) => void; title: string; detail: string; disabled?: boolean }) {
  return (
    <label className={`flex cursor-pointer items-start gap-3 ${disabled ? "cursor-not-allowed opacity-60" : ""}`}>
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(event) => onChange(event.target.checked)} className="peer sr-only" />
      <span
        aria-hidden="true"
        className="relative mt-0.5 h-5 w-9 shrink-0 rounded-[2px] border border-line bg-black/30 transition-colors after:absolute after:top-0.5 after:left-0.5 after:size-3.5 after:bg-mute after:transition-all peer-checked:border-lime peer-checked:after:translate-x-4 peer-checked:after:bg-lime peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-lime"
      />
      <span>
        <span className="label block">{title}</span>
        <span className="mt-1 block text-[13px] leading-snug text-mute">{detail}</span>
      </span>
    </label>
  );
}

import type { Tone } from "@/lib/caseStatus";
import type { CaseRecord } from "@/lib/engine/types";

const toneBorder: Record<Tone, string> = { fault: "border-ember/60 text-ember", work: "border-teal/60 text-teal", ok: "border-lime/60 text-lime" };
