import { MODEL } from "@/lib/engine/ollama";
import type { Attr, NeatlogsExport, Span, SpanKind, StoredRun } from "@/lib/engine/types";

// Sends a finished run to neatlogs through its HTTP trace injection endpoint: one nested trace per run.
// Off unless NEATLOGS_WRITE_KEY (an nlw_ ingest key) and NEATLOGS_PROJECT are set.
const INGEST_URL = process.env.NEATLOGS_INGEST_URL ?? "https://ingest.neatlogs.com/v1/trace";

type Node = {
  name: string;
  kind: string;
  project?: string;
  start: string;
  end: string;
  input?: string;
  output?: string;
  model?: string;
  tool_name?: string;
  tokens?: { prompt: number; completion: number; total: number };
  attributes: Record<string, Attr>;
  children?: Node[];
};

const KIND: Record<SpanKind, string> = { agent: "AGENT", llm: "LLM", tool: "TOOL", checkpoint: "TASK", decision: "TASK" };

export function neatlogsConfigured() {
  return Boolean(process.env.NEATLOGS_WRITE_KEY && process.env.NEATLOGS_PROJECT);
}

export async function exportToNeatlogs(run: StoredRun): Promise<NeatlogsExport> {
  const key = process.env.NEATLOGS_WRITE_KEY;
  const project = process.env.NEATLOGS_PROJECT;
  if (!key || !project) return { status: "disabled" };

  try {
    const payload = buildTrace(run, project);
    const res = await fetch(INGEST_URL, {
      method: "POST",
      headers: { authorization: `Bearer ${key}`, "content-type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      return { status: "failed", project, error: `neatlogs answered ${res.status}. ${text.slice(0, 140)}`.trim() };
    }
    const body = (await res.json().catch(() => ({}))) as { trace_id?: string; spans?: number | unknown[] };
    return { status: "sent", project, traceId: body.trace_id, spans: Array.isArray(body.spans) ? body.spans.length : body.spans };
  } catch (error) {
    return { status: "failed", project, error: error instanceof Error ? error.message : "could not reach neatlogs" };
  }
}

export function buildTrace(run: StoredRun, project: string): Node {
  const t0 = new Date(run.meta.startedAt).getTime();
  const iso = (ms: number) => new Date(t0 + ms).toISOString();

  // The last event for a span id is its final state.
  const spans = new Map<string, Span>();
  for (const event of run.events) if (event.type === "span.start" || event.type === "span.end") spans.set(event.span.id, event.span);

  const kids = new Map<string | null, Span[]>();
  for (const span of spans.values()) {
    const parent = span.parentId && spans.has(span.parentId) ? span.parentId : null;
    kids.set(parent, [...(kids.get(parent) ?? []), span]);
  }

  const toNode = (span: Span): Node => {
    // neatlogs drops attributes outside its own namespace, so everything is prefixed.
    const attributes: Record<string, Attr> = { "neatlogs.resolver.agent": span.agent, "neatlogs.resolver.status": span.status };
    for (const [k, v] of Object.entries(span.attrs)) attributes[`neatlogs.resolver.${k}`] = v;
    if (span.costUsd !== undefined) attributes["neatlogs.resolver.cost_usd"] = span.costUsd;

    const node: Node = {
      name: span.name,
      kind: KIND[span.kind],
      start: iso(span.startMs),
      end: iso(span.endMs ?? span.startMs),
      attributes,
    };

    if (span.kind === "tool") {
      const { result, error, ...args } = span.attrs;
      node.tool_name = span.name;
      node.input = JSON.stringify(args);
      node.output = String(result ?? error ?? "");
    }
    if (span.kind === "llm") {
      node.model = MODEL;
      node.input = span.attrs.prompt === undefined ? undefined : String(span.attrs.prompt);
      node.output = span.attrs.output === undefined ? String(span.attrs.reason ?? "") : String(span.attrs.output);
      attributes["neatlogs.llm.provider"] = "ollama";
      if (span.tokensIn !== undefined) node.tokens = { prompt: span.tokensIn, completion: span.tokensOut ?? 0, total: span.tokensIn + (span.tokensOut ?? 0) };
    }

    const children = (kids.get(span.id) ?? []).sort((a, b) => a.startMs - b.startMs).map(toNode);
    if (children.length > 0) node.children = children;
    return node;
  };

  const end = run.events.find((e) => e.type === "run.end");
  const result = end && end.type === "run.end" ? end.result : null;
  return {
    name: `merchant-ops-resolver ${run.meta.id}`,
    kind: "WORKFLOW",
    project,
    start: iso(0),
    end: iso(result?.durationMs ?? 0),
    input: run.meta.instruction,
    output: result?.summary ?? "",
    attributes: {
      "neatlogs.resolver.run_id": run.meta.id,
      "neatlogs.resolver.outcome": result?.outcome ?? "unknown",
      "neatlogs.resolver.chaos": run.meta.chaos,
      "neatlogs.resolver.memory_hit": result?.memoryHit ?? false,
    },
    children: (kids.get(null) ?? []).sort((a, b) => a.startMs - b.startMs).map(toNode),
  };
}

