// Standalone SDK smoke test: in-memory exporter, no network export, real Ollama call.
const { BasicTracerProvider, SimpleSpanProcessor, InMemorySpanExporter } = require("@opentelemetry/sdk-trace-base");
const neat = require("neatlogs");
const OpenAI = require("openai").default ?? require("openai").OpenAI ?? require("openai");

(async () => {
  const exporter = new InMemorySpanExporter();
  const provider = new BasicTracerProvider({ spanProcessors: [new SimpleSpanProcessor(exporter)] });
  await neat.init({ apiKey: "smoke_test_key", workflowName: "smoke", tracerProvider: provider, endpoint: "http://127.0.0.1:9", registerShutdownHandlers: false });

  const client = neat.wrapOpenAI(new OpenAI({ baseURL: "http://127.0.0.1:11434/v1", apiKey: "ollama", maxRetries: 0 }));

  await neat.trace({ name: "resolve-merchant-case", kind: "WORKFLOW", input: "hello" }, async (root) => {
    root.setAttribute("output.value", "done");
    console.log("root traceId:", root.spanContext().traceId);
    await neat.trace({ name: "coordinator.run", kind: "AGENT" }, async () => {
      await neat.trace({ name: "search_memory", kind: "RETRIEVER", input: { pattern: "X" }, attributes: { "neatlogs.retriever.query": "X", "neatlogs.retriever.top_k": 1 } }, async () => ({ hit: false }));
      await neat.trace({ name: "policy_check", kind: "GUARDRAIL", input: { action: "a" } }, async (s) => {
        s.setAttribute("neatlogs.guardrail.passed", true);
        return { allowed: true };
      });
      await neat.traceToolOpenAI("get_settlement", async () => ({ status: "FAILED" }))({ txn: "48213" });
      const res = await client.chat.completions.create(
        { model: "llama2", messages: [{ role: "user", content: "Say hello in four words." }], max_tokens: 12, temperature: 0.2 },
        { signal: AbortSignal.timeout(90000) },
      );
      console.log("usage:", JSON.stringify(res.usage), "finish:", res.choices[0].finish_reason, "text:", JSON.stringify(res.choices[0].message.content));
    });
  });

  await neat.flush();
  const spans = exporter.getFinishedSpans();
  const byId = new Map(spans.map((s) => [s.spanContext().spanId, s]));
  const depth = (s) => { const p = s.parentSpanContext?.spanId ?? s.parentSpanId; return p && byId.has(p) ? 1 + depth(byId.get(p)) : 0; };
  console.log("spans exported:", spans.length);
  for (const s of spans.sort((a, b) => a.startTime[1] - b.startTime[1])) {
    const a = s.attributes;
    console.log(`${"  ".repeat(depth(s))}${s.name} | kind=${a["openinference.span.kind"] ?? a["neatlogs.span.kind"]} | trace=${s.spanContext().traceId.slice(0, 8)} | tokens=${a["llm.token_count.prompt"] ?? a["gen_ai.usage.input_tokens"] ?? "-"}/${a["llm.token_count.completion"] ?? a["gen_ai.usage.output_tokens"] ?? "-"} | model=${a["llm.model_name"] ?? a["gen_ai.request.model"] ?? "-"}`);
  }
  await neat.shutdown();
  process.exit(0);
})().catch((e) => { console.error("SMOKE FAILED:", e); process.exit(1); });

