  const plain = plainSummary(s, decision, diag, expectedResolved);
  const greeting = `Hello ${merchant.name} team,`;
  // The greeting is added here rather than asked of the model, which saves tokens and keeps the name right.
  const promise = ctx
    .narrate({
      agent: "closure",
      parent,
      name: "llm.draft_merchant_message",
      system: SYSTEM,
      prompt: `Rewrite this for the owner of ${merchant.name} in one or two short, polite sentences. Do not include a greeting or a sign-off. Do not invent details, names, dates or promises. Text: ${plain}`,
      fallback: `${greeting} ${plain}`,
      maxTokens: 70,
      timeoutMs: DRAFT_BUDGET_MS,
    })
    .then((r) => (r.narrated ? { text: `${greeting} ${r.text}`, narrated: true } : r));
  ctx.pending.push(promise);
  let done = false;
  void promise.then(() => (done = true));
  return { expectedResolved, promise, isDone: () => done };
}

