// Runs the engine twice over HTTP and saves each stored run as JSON for the landing page figures.
import fs from "node:fs";
const dir = process.argv[2];
const instruction = "Sharma Kirana's settlement for txn #48213 failed. Investigate and resolve.";

async function run(chaos, name) {
  const res = await fetch("http://localhost:3000/api/runs", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ instruction, chaos, llm: false, speed: 1 }),
  });
  const reader = res.body.getReader();
  let id = null;
  const dec = new TextDecoder();
  let buf = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    const m = buf.match(/"id":"(run_[0-9a-f]+)"/);
    if (m) id = m[1];
  }
  const stored = await (await fetch(`http://localhost:3000/api/runs/${id}`)).json();
  fs.writeFileSync(`${dir}/${name}.json`, JSON.stringify(stored));
  const end = stored.events.find((e) => e.type === "run.end");
  console.log(name, id, end.result.outcome, end.result.durationMs + "ms", "spans", end.result.spanCount, "ckpts", end.result.checkpointCount, "memoryHit", end.result.memoryHit);
}

await run(false, "run-plain");
await run(true, "run-chaos");

// Turns the two captured runs into lib/sampleRun.ts, the real data behind the landing page figures.
import fs from "node:fs";
const [dir, out] = process.argv.slice(2);
const load = (n) => JSON.parse(fs.readFileSync(`${dir}/${n}.json`, "utf8"));
const plain = load("run-plain");
const chaos = load("run-chaos");

const fmt = (ms) => (ms < 1000 ? `${Math.round(ms)} ms` : `${(ms / 1000).toFixed(1)} s`);

function finalSpans(run) {
  const m = new Map();
  for (const e of run.events) if (e.type === "span.start" || e.type === "span.end") m.set(e.span.id, e.span);
  return [...m.values()];
}
const result = (run) => run.events.find((e) => e.type === "run.end").result;

// ---- trace waterfall and checkpoint chain, from the run with the forced timeout ----
const spans = finalSpans(chaos);
const byId = new Map(spans.map((s) => [s.id, s]));
const depth = (s) => (s.parentId && byId.has(s.parentId) ? 1 + depth(byId.get(s.parentId)) : 0);
const kindOf = (s) => (s.status === "error" ? "retry" : s.kind === "decision" ? "decision" : s.kind);
const trace = spans
  .filter((s) => s.kind !== "checkpoint")
  .sort((a, b) => a.startMs - b.startMs || depth(a) - depth(b))
  .map((s) => ({ kind: kindOf(s), name: s.name, depth: depth(s), start: s.startMs, ms: (s.endMs ?? s.startMs) - s.startMs, label: fmt((s.endMs ?? s.startMs) - s.startMs) }));

const resumed = chaos.events.map((e) => (e.type === "log" ? e.text.match(/resumed from (ckpt_\w+)/) : null)).find(Boolean)?.[1] ?? null;
const memoryLine = chaos.events.find((e) => e.type === "log" && /^Memory hit/.test(e.text))?.text ?? null;
const checkpoints = chaos.events
  .filter((e) => e.type === "checkpoint")
  .map((e) => ({ id: e.checkpoint.id, label: e.checkpoint.label, agent: e.checkpoint.agent, hash: e.checkpoint.hash.slice(0, 12), parent: e.checkpoint.parentId }));

// ---- step timings for the case scene, from the plain run ----
const ps = finalSpans(plain);
const find = (name) => ps.find((s) => s.name === name);
const dur = (s) => (s.endMs ?? s.startMs) - s.startMs;
const ck = (label) => plain.events.find((e) => e.type === "checkpoint" && e.checkpoint.label === label).checkpoint.atMs;
const resolution = find("resolution.run");
const timings = {
  received: fmt(dur(ps.find((s) => s.name === "get_settlement"))),
  planned: `3 workers, ${fmt(ck("plan"))}`,
  investigated: `memory hit, ${fmt(dur(find("investigation.run")))}`,
  applied: fmt(ck("retrigger") - resolution.startMs),
  verified: `status=SETTLED, ${fmt(dur(find("resolution.verify")))}`,
  closed: `KB updated, ${fmt(dur(find("closure.run")))}`,
  traced: `${result(plain).spanCount} spans`,
};

const body = `// Generated from two real runs of case txn 48213 (see scripts in the repo history). Not hand-written.
// The trace and checkpoints come from a run with the forced bank timeout. The step timings come from a
