const ranked = [...findings].sort((a, b) => b.confidence - a.confidence);
const rootCause =
  ranked.length > 1 && ranked[1].confidence > 0.5
    ? "Demand spike, plus one suspicious device cluster"
    : ranked[0].id === "device_cluster"
      ? "Suspicious device cluster, demand spike not supported"
      : "Demand spike with no sign of fraud";
return { rootCause, findings };

// ---- batch runs: an uploaded file, one case at a time --------------------------------------------

export type BatchCaseResult = {
  index: number;
  txn: string;
  merchant: string;
  amount: number;
  status: "FAILED" | "HELD";
  pattern: FailureCode;
  reason: string;
  expected: "resolved" | "escalated" | null;
  runId: string | null;
  outcome: Outcome;
  rootCause: string;
  fix: string;
  verification: string;
  subject: string | null;
  durationMs: number;
  toolCalls: number;
  costUsd: number;
  memoryHit: boolean;
  // Whether the outcome matched the file's own expected_outcome column. Null when the file has none.
  matched: boolean | null;
};

export type BatchSummary = {
  processed: number;
  resolved: number;
  escalated: number;
  failed: number;
  amountResolved: number;
  amountEscalated: number;
  wallMs: number;
  costUsd: number;
  humanUsdAvoided: number;
  memoryHits: number;
  coldAvgToolCalls: number | null;
  warmAvgToolCalls: number | null;
  labelled: number;
  matched: number;
};

export type BatchOptions = { chaos: boolean; llm: boolean; freshMemory: boolean };

export type BatchEvent =
  | { type: "batch.start"; id: string; report: IntakeReport; options: BatchOptions }
  | { type: "case.start"; index: number }
  | { type: "case.end"; result: BatchCaseResult }
  | { type: "batch.end"; summary: BatchSummary };

export type StoredBatch = { id: string; report: IntakeReport; options: BatchOptions; results: BatchCaseResult[]; summary: BatchSummary };

export type RunOptions = {

