}

// Usage: node batch-run.mjs <file> [chaos=0|1] [fresh=1|0]
import fs from "node:fs";
const [file, chaos = "0", fresh = "1"] = process.argv.slice(2);
const text = fs.readFileSync(file, "utf8");
const res = await fetch("http://localhost:3000/api/batches", {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({ text, filename: file.split(/[\\/]/).pop(), chaos: chaos === "1", llm: false, freshMemory: fresh === "1" }),
});
if (!res.ok) {
  console.log("HTTP", res.status, await res.text());
  process.exit(1);
}
const reader = res.body.getReader();
const dec = new TextDecoder();
let buf = "";
const events = [];
for (;;) {
  const { done, value } = await reader.read();
  if (done) break;
  buf += dec.decode(value, { stream: true });
  let i;
  while ((i = buf.indexOf("\n\n")) >= 0) {
    events.push(JSON.parse(buf.slice(0, i).replace(/^data: /, "")));
    buf = buf.slice(i + 2);
  }
}
const start = events.find((e) => e.type === "batch.start");
const r = start.report;
console.log(`batch ${start.id}: ${r.cases.length} cases, ${r.history} history rows, ${r.rejected.length} rejected, ${r.rowCount} rows`);
console.log("columns:", r.columns.map((c) => `${c.source}>${c.field}`).join(", "));
console.log("ignored:", r.ignoredColumns.join(", ") || "none");
for (const x of r.rejected) console.log(`  rejected row ${x.row}: ${x.reason}`);
for (const e of events.filter((e) => e.type === "case.end")) {
  const x = e.result;
  console.log(`${String(x.txn).padEnd(6)} ${x.merchant.padEnd(20)} ${x.pattern.padEnd(22)} ${x.outcome.padEnd(9)} calls=${String(x.toolCalls).padStart(2)} ${String(x.durationMs).padStart(5)}ms ${x.memoryHit ? "warm" : "cold"} expected=${x.expected ?? "-"} matched=${x.matched}`);
  console.log(`        cause: ${x.rootCause} | fix: ${x.fix} | subject: ${x.subject}`);
}
console.log("SUMMARY", JSON.stringify(events.find((e) => e.type === "batch.end").summary));

