37	export function batchReducer(state: BatchState, action: BatchAction): BatchState {
38	  switch (action.type) {
39	    case "file":
40	      return { ...initialBatchState, phase: "preview", fileName: action.fileName, text: action.text, report: action.report };
41	    case "error":
42	      return { ...state, phase: "error", error: action.message, fileName: action.fileName ?? state.fileName, report: null };
43	    case "start":
44	      return { ...state, phase: "running", results: [], summary: null, current: null, batchId: null, error: null };
45	    case "load":
46	      return {
47	        ...initialBatchState,
48	        phase: "done",
49	        fileName: action.batch.report.filename,
50	        report: action.batch.report,
51	        batchId: action.batch.id,
52	        options: action.batch.options,
53	        results: action.batch.results,
54	        summary: action.batch.summary,
55	      };
56	    case "event": {
57	      const event = action.event;
58	      if (event.type === "batch.start") return { ...state, phase: "running", batchId: event.id, report: event.report, options: event.options };
59	      if (event.type === "case.start") return { ...state, current: event.index };
60	      if (event.type === "case.end") return { ...state, current: null, results: [...state.results, event.result] };
