97	export type NeatlogsExport = {
98	  status: "disabled" | "traced";
99	  traceId?: string;
100	};
101	
102	export type RunEvent =
103	  | { type: "run.start"; run: RunMeta }
104	  | { type: "agent"; agent: AgentId; state: AgentState }
105	  | { type: "span.start"; span: Span }
106	  | { type: "span.end"; span: Span }
107	  | { type: "log"; atMs: number; agent: AgentId; level: LogLevel; text: string }
108	  | { type: "checkpoint"; checkpoint: Checkpoint }
109	  | { type: "status"; status: string; tone: Tone; repair: number }
110	  | { type: "case"; patch: Partial<CaseRecord> }
111	  | { type: "cost"; cost: Cost }
112	  | { type: "run.end"; result: RunResult }
113	  | { type: "export"; neatlogs: NeatlogsExport };
114	
115	export type RunSummary = {
116	  id: string;
117	  instruction: string;
118	  startedAt: string;
119	  txn: string | null;
120	  pattern: string | null;
121	  outcome: Outcome;
122	  chaos: boolean;
123	  memoryHit: boolean;
124	  durationMs: number;
125	  toolCalls: number;
126	  llmCalls: number;
127	  costUsd: number;
128	};
129	
130	export type StoredRun = { meta: RunMeta; events: RunEvent[]; summary: RunSummary | null };
