  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({ mode, label: "why-not test" }),
});
if (!res.ok) {
  console.log("HTTP", res.status, await res.text());
  process.exit(1);
}
const events = (await res.text()).split("\n\n").filter(Boolean).map((l) => JSON.parse(l.replace(/^data: /, "")));
const results = events.filter((e) => e.type === "case.end").map((e) => e.result);
const s = events.find((e) => e.type === "batch.end").summary;
console.log(`mode=${mode}: ${results.length} cases | matched ${s.matched}/${s.labelled} | unsafe cases ${s.unsafe} | recoveries ${s.recoveries}`);
console.log(`whyNot present on ${results.filter((r) => r.whyNot).length} of ${results.length}`);
const seen = new Set();
for (const r of results) {
  if (!r.whyNot) continue;
  const key = `${r.pattern}|${r.whyNot.question}|${r.whyNot.blockers.map((b) => b.rule).join("+")}`;
  if (seen.has(key)) continue;
  seen.add(key);
  const w = r.whyNot;
