  for (const l of w.wouldChange) console.log(`  would change: ${l}`);
  if (w.confidence) console.log(`  confidence: ${w.confidence.label} ${Math.round(w.confidence.value * 100)}% needed=${w.confidence.needed}`);
}
const unsafe = results.filter((r) => r.unsafe.length);
for (const r of unsafe) console.log(`UNSAFE ${r.txn} [${r.category}]: ${r.unsafe.join("; ")}`);

