12	// Starts a case and streams every event back as server-sent events.
13	export async function POST(request: Request) {
14	  const body = (await request.json().catch(() => null)) as { instruction?: unknown; chaos?: unknown; llm?: unknown; speed?: unknown } | null;
15	  const instruction = typeof body?.instruction === "string" ? body.instruction.trim() : "";
16	  if (instruction.length < 3 || instruction.length > 400) {
17	    return Response.json({ error: "Instruction must be between 3 and 400 characters." }, { status: 400 });
18	  }
19	  if ((g.__active ?? 0) >= MAX_CONCURRENT) {
20	    return Response.json({ error: "Too many cases running. Try again in a few seconds." }, { status: 429 });
21	  }
22	
23	  const speed = typeof body?.speed === "number" ? Math.min(Math.max(body.speed, 0), 1) : 1;
24	  const encoder = new TextEncoder();
25	  g.__active = (g.__active ?? 0) + 1;
26	
27	  const stream = new ReadableStream({
28	    async start(controller) {
29	      try {
30	        await executeRun({ instruction, chaos: body?.chaos === true, llm: body?.llm !== false, speed }, (event) => {
31	          controller.enqueue(encoder.encode(`data: ${JSON.stringify(event)}\n\n`));
32	        });
33	      } finally {
34	        g.__active = Math.max((g.__active ?? 1) - 1, 0);
35	        try {
36	          controller.close();
37	        } catch {
38	          // already closed because the client left
39	        }
40	      }
41	    },
42	  });
43	
