3	// neatlogs tracing. Everything here is a pass-through until NEATLOGS_API_KEY is set, so the app behaves
4	// identically with tracing off. The SDK itself is initialised once at startup in instrumentation.ts.
5	export const telemetryOn = () => Boolean(process.env.NEATLOGS_API_KEY);
6	
7	type AttrValue = string | number | boolean;
8	
9	// The part of an active span the engine uses.
10	export type TraceSpan = {
11	  setAttribute(key: string, value: AttrValue): unknown;
12	  spanContext(): { traceId: string };
13	};
14	
15	const NOOP: TraceSpan = { setAttribute: () => undefined, spanContext: () => ({ traceId: "" }) };
16	
17	export type TracedKind = "WORKFLOW" | "AGENT" | "CHAIN" | "RETRIEVER" | "GUARDRAIL";
18	
19	// Runs `fn` inside a neatlogs span. Spans nest under whichever span is active, so the trace tree
20	// follows the call hierarchy. Errors are recorded on the span and rethrown by the SDK.
21	export function traced<T>(
22	  options: { name: string; kind: TracedKind; input?: unknown; attributes?: Record<string, AttrValue> },
23	  fn: (span: TraceSpan) => Promise<T>,
24	): Promise<T> {
25	  if (!telemetryOn()) return fn(NOOP);
26	  return trace(options, (span) => fn(span));
27	}
28	
29	// A TOOL span that records the arguments as input and the return value as output.
30	export function tracedTool<R>(name: string, args: Record<string, AttrValue>, fn: () => Promise<R>): Promise<R> {
31	  if (!telemetryOn()) return fn();
