// Runs the three traced cases and prints their run ids and neatlogs trace ids.
const base = "http://localhost:3000";
const sse = async (url, body) => {
  const res = await fetch(`${base}${url}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`${url} -> HTTP ${res.status} ${await res.text()}`);
  return (await res.text()).split("\n\n").filter(Boolean).map((l) => JSON.parse(l.replace(/^data: /, "")));
};
const traceOf = async (runId) => {
  const res = await fetch(`${base}/api/runs/${runId}`);
  const stored = await res.json();
  const exp = stored.events.find((e) => e.type === "export");
  const resumed = stored.events.filter((e) => e.type === "log" && e.text.startsWith("Checkpoint: resumed from")).length;
  const keys = stored.events.filter((e) => e.type === "span.end" && e.span.name === "tool.retrigger_settlement").map((e) => e.span.attrs?.idempotencyKey ?? e.span.attrs?.["input.idempotencyKey"] ?? null);
  return { exp: exp?.neatlogs, resumed, keys };
};

const which = process.argv[2];

if (which === "recovery") {
  const events = await sse("/api/runs", { instruction: "Sharma Kirana's settlement for txn #48213 failed. Investigate and resolve.", chaos: true, llm: true });
  const start = events.find((e) => e.type === "run.start").run;
