// Smoke test of the production server. Usage: node prod-smoke.mjs <port>
import { readFileSync } from "node:fs";
const base = `http://localhost:${process.argv[2] ?? "3200"}`;
const sse = async (url, body) => {
  const res = await fetch(`${base}${url}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`${url} -> HTTP ${res.status} ${await res.text()}`);
  return (await res.text()).split("\n\n").filter(Boolean).map((l) => JSON.parse(l.replace(/^data: /, "")));
};
const ok = (name, pass, detail = "") => console.log(`${pass ? "PASS" : "FAIL"}  ${name}${detail ? "  " + detail : ""}`);

// 1. single case with an injected failure
let t = Date.now();
const run = await sse("/api/runs", { instruction: "Sharma Kirana's settlement for txn #48213 failed. Investigate and resolve.", chaos: true, llm: true });
const start = run.find((e) => e.type === "run.start").run;
const end = run.find((e) => e.type === "run.end").result;
const exp = run.find((e) => e.type === "export")?.neatlogs;
ok("single case resolves after an injected failure", end.outcome === "resolved" && end.chainValid, `outcome=${end.outcome} chainValid=${end.chainValid} ${Date.now() - t} ms`);
ok("model unavailable, built-in wording used", start.llm.available === false && end.report?.narrated === false);
ok("tracing is off without a key", exp?.status === "disabled", `export=${exp?.status}`);
ok("explanation present", Boolean(end.whyNot?.answer));
const reopened = await fetch(`${base}/api/runs/${start.id}`);
ok("run can be reopened by id", reopened.ok, `GET /api/runs/${start.id} -> ${reopened.status}`);

// 2. batch upload of the sample file
t = Date.now();
const csv = readFileSync(new URL("../../../../../../../../../../Coding/merchant-ops-resolver/public/sample-settlements.csv", import.meta.url), "utf8");
const batch = await sse("/api/batches", { text: csv, filename: "sample-settlements.csv", chaos: false, llm: false, freshMemory: true });
const bs = batch.find((e) => e.type === "batch.end").summary;
const bid = batch.find((e) => e.type === "batch.start").id;
ok("sample batch processes all 13 cases", bs.processed === 13 && bs.matched === bs.labelled, `processed=${bs.processed} resolved=${bs.resolved} escalated=${bs.escalated} matched=${bs.matched}/${bs.labelled} unsafe=${bs.unsafe} ${Date.now() - t} ms`);
const reb = await fetch(`${base}/api/batches/${bid}`);
ok("batch can be reopened by id", reb.ok, `GET /api/batches/${bid} -> ${reb.status}`);

// 3. one scorecard case
const ev = await sse("/api/eval", { mode: "ambiguous", unsafeRetry: false, txns: ["80001"], label: "prod smoke" });
const r = ev.find((e) => e.type === "case.end").result;
ok("scorecard single case: paid once, nothing unsafe", r.payouts === 1 && r.unsafe.length === 0, `payouts=${r.payouts} unsafe=${r.unsafe.length}`);

// 4. guard: a second batch while one runs, and a bad upload
const bad = await fetch(`${base}/api/batches`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text: "not,a,settlement,file\n1,2,3,4", filename: "x.csv" }) });
ok("a bad file is rejected with a clear error", bad.status === 400, `HTTP ${bad.status}`);

