// Stands in for neatlogs: receives whatever the SDK exports, then looks for the bank's internal counters in it.
// Usage: node otlp-check.mjs <app port> <receiver port>
import http from "node:http";
import zlib from "node:zlib";

const [appPort = "3100", recvPort = "4319"] = process.argv.slice(2);
const bodies = [];

const server = http.createServer((req, res) => {
  const chunks = [];
  req.on("data", (c) => chunks.push(c));
  req.on("end", () => {
    let buf = Buffer.concat(chunks);
    try {
      if (req.headers["content-encoding"] === "gzip") buf = zlib.gunzipSync(buf);
    } catch {
      // keep the raw bytes
    }
    bodies.push({ url: req.url, type: req.headers["content-type"], enc: req.headers["content-encoding"], size: buf.length, text: buf.toString("latin1") });
    res.writeHead(200, { "content-type": "application/json" });
    res.end("{}");
  });
});
await new Promise((r) => server.listen(Number(recvPort), "127.0.0.1", r));

// One careless-retry case, the one where the counter would matter most.
const res = await fetch(`http://localhost:${appPort}/api/eval`, {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({ mode: "ambiguous", unsafeRetry: true, txns: ["80001"], label: "otlp check" }),
});
const events = (await res.text()).split("\n\n").filter(Boolean).map((l) => JSON.parse(l.replace(/^data: /, "")));
const r = events.find((e) => e.type === "case.end").result;
console.log(`case 80001 careless: outcome=${r.outcome} world payouts=${r.payouts} unsafe=${r.unsafe.length}`);

await new Promise((r2) => setTimeout(r2, 15000));
server.close();

const all = bodies.map((b) => b.text).join("\n");
const count = (s) => (all.match(new RegExp(s, "g")) ?? []).length;
console.log(`exports received: ${bodies.length}, total bytes: ${bodies.reduce((n, b) => n + b.size, 0)}`);
console.log(`paths: ${[...new Set(bodies.map((b) => b.url))].join(", ")}`);
console.log(`span name get_settlement seen: ${count("get_settlement")}`);
console.log(`retrigger_settlement seen: ${count("retrigger_settlement")}, retry1 key seen: ${count("_retry1")}`);
console.log(`"payouts" occurrences: ${count("payouts")}`);
console.log(`"idempotencyKeys" occurrences: ${count("idempotencyKeys")}`);

// Keeps the foreground command alive so the SDK can flush its last batch before the server is stopped.
const seconds = Number(process.argv[2] ?? "45");
console.log(`holding ${seconds} s so the trace exporter can flush...`);
await new Promise((r) => setTimeout(r, seconds * 1000));
console.log("done");
